# 5. SOLANA CLIENT
# ============================================================================

class SolanaClientV10:
    def __init__(self):
        self.rpcs = list(SOLANA_RPCS)
        self.current = 0
        self.fail_count = defaultdict(int)

    def _post(self, method, params, timeout=12):
        last_err = None
        for attempt in range(len(self.rpcs) * 2):
            rpc = self.rpcs[self.current]
            try:
                r = requests.post(rpc, json={
                    "jsonrpc": "2.0", "id": 1, "method": method, "params": params
                }, timeout=timeout, headers={"Content-Type": "application/json"})
                if r.ok:
                    self.fail_count[rpc] = 0
                    return r.json()
                if r.status_code == 429:
                    wait = 2 ** attempt + random.uniform(0, 1)
                    log.warning(f"RPC {rpc[:30]}... rate limited, esperando {wait:.1f}s")
                    time.sleep(wait)
                    self.fail_count[rpc] += 1
                    continue
                self.fail_count[rpc] += 1
            except Exception as e:
                self.fail_count[rpc] += 1
                last_err = e
                if attempt < len(self.rpcs) * 2 - 1:
                    time.sleep(0.5 * (attempt + 1))
            self.current = (self.current + 1) % len(self.rpcs)
        log.warning(f"RPCs Solana falharam ({method}): {last_err}")
        return None

    def get_tx(self, sig):
        r = self._post("getTransaction", [sig, {
            "encoding": "jsonParsed",
            "commitment": "confirmed",
            "maxSupportedTransactionVersion": 0
        }], timeout=20)
        if not r:
            log.warning(f"get_tx: RPC retornou None para sig={sig[:20]}...")
            return None
        return r.get("result")

    def get_balance_usdc(self, address):
        r = self._post("getTokenAccountsByOwner",
                       [address, {"mint": USDC_MINT}, {"encoding": "jsonParsed"}])
        if not r or not r.get("result"):
            return 0.0
        total = 0.0
        for acc in r["result"].get("value", []):
            info = acc.get("account", {}).get("data", {}).get("parsed", {}).get("info", {})
            total += float(info.get("tokenAmount", {}).get("uiAmount") or 0)
        return total

    def verify_payment(self, signature, expected_amount, receiver_address, max_age=86400):
        tx = self.get_tx(signature)
        if not tx:
            return False, "tx-not-found"
        if tx.get("meta", {}).get("err"):
            return False, "tx-failed"
        block_time = tx.get("blockTime") or 0
        if block_time and (time.time() - block_time) > max_age:
            return False, "tx-too-old"
        meta = tx.get("meta", {})
        pre  = {b["accountIndex"]: b for b in meta.get("preTokenBalances", [])}
        post = {b["accountIndex"]: b for b in meta.get("postTokenBalances", [])}
        payer_addr = ""
        # Método 1: pre/post balances
        for idx, pb in post.items():
            if pb.get("mint") != USDC_MINT:
                continue
            if pb.get("owner") != receiver_address:
                continue
            pa = float(pre.get(idx, {}).get("uiTokenAmount", {}).get("uiAmount") or 0)
            po = float(pb.get("uiTokenAmount", {}).get("uiAmount") or 0)
            delta = po - pa
            if delta + 1e-9 >= expected_amount:
                for j, qb in pre.items():
                    if qb.get("mint") != USDC_MINT:
                        continue
                    qa = float(qb.get("uiTokenAmount", {}).get("uiAmount") or 0)
                    qp = float(post.get(j, {}).get("uiTokenAmount", {}).get("uiAmount") or 0)
                    if qa - qp >= expected_amount - 1e-9:
                        payer_addr = qb.get("owner", "")
                        break
                return True, {"ok": True, "delta": delta, "payer": payer_addr}
        # Método 2: inner instructions
        inner_ixs = meta.get("innerInstructions", [])
        for inner in inner_ixs:
            for ix in inner.get("instructions", []):
                prog = ix.get("programId", "")
                if "Token" in prog or prog == "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA":
                    parsed = ix.get("parsed", {})
                    ix_type = parsed.get("type", "")
                    if ix_type in ("transfer", "transferChecked"):
                        info = parsed.get("info", {})
                        dest = info.get("destination", "")
                        if "tokenAmount" in info:
                            amount_raw = int(info["tokenAmount"].get("amount", 0))
                            decimals = info["tokenAmount"].get("decimals", USDC_DECIMALS)
                            amount_ui = amount_raw / (10 ** decimals)
                        else:
                            amount_raw = int(info.get("amount", 0))
                            amount_ui = amount_raw / (10 ** USDC_DECIMALS)
                        dest_owner = None
                        for b in meta.get("postTokenBalances", []):
                            if b.get("accountIndex") == info.get("destinationIndex"):
                                dest_owner = b.get("owner")
                                break
                        if not dest_owner:
                            account_keys = tx.get("transaction", {}).get("message", {}).get("accountKeys", [])
                            dest_idx = info.get("destinationIndex")
                            if dest_idx is not None and dest_idx < len(account_keys):
                                dest_owner = account_keys[dest_idx] if isinstance(account_keys[dest_idx], str) else account_keys[dest_idx].get("pubkey")
                        if dest_owner == receiver_address and amount_ui + 1e-9 >= expected_amount:
                            payer_addr = info.get("authority", info.get("sourceOwner", ""))
                            return True, {"ok": True, "delta": amount_ui, "payer": payer_addr, "method": "inner-instruction"}
        # Método 3: logs
        logs = meta.get("logMessages", [])
        for log_entry in logs:
            if "Instruction: Transfer" in log_entry or "Instruction: TransferChecked" in log_entry:
                return True, {"ok": True, "delta": expected_amount, "payer": "", "method": "log-fallback"}
        return False, "no-matching-transfer"

    def get_recent_txs(self, address, limit=10):
        r = self._post("getSignaturesForAddress", [address, {"limit": limit}])
        return r.get("result", []) if r else []

    def get_priority_fees(self):
        r = self._post("getRecentPrioritizationFees", [])
        if not r:
            return {"mean": 0, "p90": 0}
        fees = [f.get("prioritizationFee", 0) for f in (r.get("result") or [])]
        if not fees:
            return {"mean": 0, "p90": 0}
        fees.sort()
        return {
            "mean": sum(fees) / len(fees),
            "p90":  fees[int(len(fees) * 0.9)],
            "n":    len(fees),
        }

SOL = SolanaClientV10()

# ============================================================================
# 5b. FACILITATOR CLIENT
# ============================================================================

# v24.9: timeouts curtos — cada request pendurado segura uma thread do
# gunicorn (2 workers x 6 threads). Um facilitator lento derrubava a
# latência do nó inteiro (manifests chegaram a 25s nos logs).
FAC_VERIFY_TIMEOUT = int(os.environ.get("FAC_VERIFY_TIMEOUT", "8"))
FAC_SETTLE_TIMEOUT = int(os.environ.get("FAC_SETTLE_TIMEOUT", "15"))

class FacilitatorClient:
    def __init__(self, url: str):
        self.url = url.rstrip("/")
        self.is_cdp = "cdp.coinbase.com" in self.url
        # v44.7.0: rótulo por facilitador (log e 402 carimbam quem recusou)
        self.tag = ("CDP" if self.is_cdp else
                    "GoPlausible" if "goplausible" in self.url else "PayAI")

    def _cdp_jwt(self, method: str, path: str) -> Optional[str]:
        """v21.13.3: JWT p/ CDP — suporta Ed25519 (secret base64, keys novas)
        E ECDSA ES256 (secret PEM EC, keys clássicas). O PEM pode vir com
        espaços no lugar de quebras de linha (Railway) — parseamos o corpo
        base64 direto, imune à formatação."""
        try:
            from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
            import secrets as _secrets
            sec = CDP_API_KEY_SECRET.strip()
            alg, key = "EdDSA", None
            if "BEGIN EC PRIVATE KEY" in sec:
                import re as _re
                from cryptography.hazmat.primitives.serialization import load_der_private_key
                body = sec.split("KEY-----", 1)[1].rsplit("-----END", 1)[0]
                b64 = _re.sub(r"[^A-Za-z0-9+/=]", "", body)
                key = load_der_private_key(base64.b64decode(b64), password=None)
                alg = "ES256"
            else:
                raw = base64.b64decode(sec)
                seed = raw[:32]
                key = Ed25519PrivateKey.from_private_bytes(seed)
            host_and_path = self.url.split("://", 1)[1]
            host = host_and_path.split("/", 1)[0]
            prefix = "/" + host_and_path.split("/", 1)[1] if "/" in host_and_path else ""
            now = int(time.time())
            def _b64u(b): return base64.urlsafe_b64encode(b).decode().rstrip("=")
            header = {"typ": "JWT", "alg": "EdDSA", "kid": CDP_API_KEY_ID,
                      "nonce": _secrets.token_hex(16)}
            claims = {"iss": "cdp", "sub": CDP_API_KEY_ID, "aud": ["cdp_service"],
                      "nbf": now, "exp": now + 120,
                      "uris": [f"{method} {host}{prefix}{path}"]}
            header["alg"] = alg
            signing = (_b64u(json.dumps(header, separators=(",", ":")).encode())
                       + "." + _b64u(json.dumps(claims, separators=(",", ":")).encode()))
            if alg == "ES256":
                from cryptography.hazmat.primitives import hashes as _hashes
                from cryptography.hazmat.primitives.asymmetric import ec as _ec
                from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
                der_sig = key.sign(signing.encode(), _ec.ECDSA(_hashes.SHA256()))
                r, s = decode_dss_signature(der_sig)
                sig = r.to_bytes(32, "big") + s.to_bytes(32, "big")
            else:
                sig = key.sign(signing.encode())
            return signing + "." + _b64u(sig)
        except Exception as e:
            log.warning(f"CDP JWT: {e}")
            return None

    def _headers(self, method: str = "POST", path: str = "/verify"):
        h = {"Content-Type": "application/json"}
        if self.is_cdp:
            tok = self._cdp_jwt(method, path)
            if tok:
                h["Authorization"] = f"Bearer {tok}"
        return h

    def verify(self, payment_payload: dict, requirements: dict) -> Tuple[bool, str, dict]:
        body = {
            "x402Version": payment_payload.get("x402Version", 2),
            "paymentPayload": payment_payload,
            "paymentRequirements": requirements,
        }
        try:
            hdrs = self._headers("POST", "/verify")
            r = requests.post(f"{self.url}/verify", json=body, headers=hdrs, timeout=FAC_VERIFY_TIMEOUT)
            # v21.5: retry único para 5xx transitório do facilitator
            if r.status_code >= 500:
                time.sleep(1.5)
                hdrs = self._headers("POST", "/verify")
                r = requests.post(f"{self.url}/verify", json=body, headers=hdrs, timeout=FAC_VERIFY_TIMEOUT)
            if not r.ok:
                log.warning(f"⚠️ facilitator /verify body enviado: {json.dumps(body)[:600]}")
                return False, f"facilitator-{r.status_code}:{r.text[:300]}", {}
            data = r.json() if r.text else {}
            return bool(data.get("isValid") or data.get("valid")), \
                   data.get("invalidReason", ""), data
        except Exception as e:
            return False, f"facilitator-error:{e}", {}

    def settle(self, payment_payload: dict, requirements: dict,
               bazaar: Optional[dict] = None,
               resource: Optional[dict] = None) -> Tuple[bool, dict]:
        try:
            pp = payment_payload
            # v21.13: blob de discovery do Bazaar — a CDP cataloga o endpoint
            # quando processa o settle com esse metadata (indexação automática).
            # v41 FIX CRÍTICO — A VENDA ACONTECIA MAS NÃO VIRAVA CATÁLOGO.
            # Docs CDP (quickstart-for-sellers, jul/2026): o payment payload
            # enviado ao facilitador DEVE incluir paymentPayload.resource — é
            # esse campo que o Bazaar/Agentic.Market usa para associar o settle
            # ao recurso e indexá-lo. Sem ele, cada settle em Base era invisível
            # para o diretório onde os compradores descobrem serviços.
            # ---------------------------------------------------------------
            # v41.1 — `resource` VIROU OPT-IN. Leia antes de ligar.
            #
            # O patch v41 passou a injetar pp["resource"] em todo settle CDP,
            # com a justificativa de que o Bazaar precisa dele para indexar.
            # Fui verificar na extensão oficial do Bazaar (coinbase/x402,
            # go/extensions/bazaar) e o que está documentado é outra coisa:
            #
            #   "V2: Extensions are in PaymentPayload.Extensions
            #    (client copied from PaymentRequired)"
            #   "V1: Discovery info is in PaymentRequirements.OutputSchema"
            #
            # Ou seja: o canal documentado é `extensions`, que este código já
            # usava. Não achei `paymentPayload.resource` em lugar nenhum — nem
            # no quickstart-for-sellers, nem na extensão Go.
            #
            # O risco é assimétrico. Se o facilitador ignorar o campo, não
            # ganhamos nada. Se validar o schema estritamente, um campo
            # desconhecido em paymentPayload pode fazer o settle ser REJEITADO
            # — e Base é a maioria das vendas. Perder receita para testar uma
            # hipótese não verificada é troca ruim.
            #
            # Então: desligado por padrão, ligável por env para testar.
            #   CDP_SEND_RESOURCE=1  → volta ao comportamento do v41
            # Teste com $0.01 em Base e confira /receipts antes de deixar ligado.
            # ---------------------------------------------------------------
            if self.is_cdp and (bazaar or (resource and CDP_SEND_RESOURCE)):
                pp = dict(payment_payload)
                if bazaar:
                    ext = dict(pp.get("extensions") or {})
                    ext["bazaar"] = bazaar
                    pp["extensions"] = ext
                if resource and CDP_SEND_RESOURCE:
                    pp["resource"] = resource
                    log.info("🧪 settle CDP com paymentPayload.resource "
                             "(experimental, CDP_SEND_RESOURCE=1)")
            r = requests.post(f"{self.url}/settle", json={
                "x402Version": pp.get("x402Version", 2),
                "paymentPayload": pp,
                "paymentRequirements": requirements,
            }, headers=self._headers("POST", "/settle"), timeout=FAC_SETTLE_TIMEOUT)
            if not r.ok:
                return False, {"error": f"facilitator-{r.status_code}", "body": r.text[:400]}
            # v21.14: EXTENSION-RESPONSES é o mecanismo oficial de diagnóstico da
            # indexação Bazaar — logar sempre no settle CDP (presente ou ausente).
            if self.is_cdp:
                _ext = r.headers.get("EXTENSION-RESPONSES") or r.headers.get("extension-responses")
                log.info(f"🏪 settle CDP ok | EXTENSION-RESPONSES: {_ext or 'AUSENTE'}")
            return True, r.json()
        except Exception as e:
            return False, {"error": str(e)}

    def get_svm_fee_payer(self) -> Optional[str]:
        """Consulta /supported no facilitador e extrai o signer (feePayer) para redes solana:*.
        Resultado é cacheado no processo — evita bater no facilitador a cada 402 emitido."""
        cached = getattr(self, "_svm_fee_payer_cache", None)
        cached_at = getattr(self, "_svm_fee_payer_cache_at", 0)
        if cached and (time.time() - cached_at) < 3600:
            return cached
        try:
            r = requests.get(f"{self.url}/supported", timeout=10)
            if not r.ok:
                return cached
            data = r.json() if r.text else {}
            signers = data.get("signers", {}) or {}
            fee_payer = None
            for net_pattern, addrs in signers.items():
                if net_pattern.startswith("solana") and addrs:
                    fee_payer = addrs[0]
                    break
            if fee_payer:
                self._svm_fee_payer_cache = fee_payer
                self._svm_fee_payer_cache_at = time.time()
                return fee_payer
        except Exception as e:
            log.warning(f"⚠️ Falha ao buscar feePayer do facilitador: {e}")
        return cached

FACILITATOR = FacilitatorClient(FACILITATOR_URL) if USE_FACILITATOR else None
