# ============================================================================
# 7. GEOIP
# ============================================================================

_GEO_CACHE: Dict[str, Tuple[str, int]] = {}

def geo_country(ip: str) -> str:
    if not ip or ip.startswith("127.") or ip.startswith("10.") or ip.startswith("192.168."):
        return ""
    cached = _GEO_CACHE.get(ip)
    if cached and time.time() - cached[1] < 3600:
        return cached[0]
    try:
        r = requests.get(f"http://ip-api.com/json/{ip}?fields=countryCode", timeout=3)
        cc = r.json().get("countryCode", "") if r.ok else ""
        _GEO_CACHE[ip] = (cc, int(time.time()))
        return cc
    except Exception:
        return ""

def is_geo_blocked(ip: str) -> bool:
    if not GEOIP_ENABLED or not GEO_BLOCKED_COUNTRIES:
        return False
    cc = geo_country(ip)
    return cc in GEO_BLOCKED_COUNTRIES

# ============================================================================
# 8. LLM (com DeepSeek e Claude)
# ============================================================================

# v39: modelos vêm de env. O motivo é operacional, não estético — a v38 tinha
# "gemini-2.0-flash-exp" fixo no código; esse modelo foi RETIRADO pelo Google e
# devolvia 404 em toda chamada. Com o Groq no teto de TPD ao mesmo tempo, a
# cadeia inteira caía e os endpoints pagos entregavam texto vazio. Modelo em
# env = troca sem redeploy quando um provedor descontinua algo.
DEEPSEEK_MODEL = os.environ.get("DEEPSEEK_MODEL", "deepseek-chat")
CLAUDE_MODEL   = os.environ.get("CLAUDE_MODEL",   "claude-sonnet-4-5")
GROQ_MODEL     = os.environ.get("GROQ_MODEL",     "").strip()
# v47.1.0: sem default fixo. Vazio = descoberta automatica via /models.
# Registro: llama-3.3-70b-versatile foi DESCOMISSIONADO pela Groq em
# 2026-08-16 e derrubou a sintese por 2 dias. Modelo fixo nunca mais.
# v39.6: sem default. Vazio = descoberta automática via ListModels.
GEMINI_MODEL   = os.environ.get("GEMINI_MODEL",   "").strip()

LLM_CACHE_TTL  = int(os.environ.get("LLM_CACHE_TTL", "900"))
_LLM_CACHE: Dict[str, tuple] = {}
_LLM_CACHE_LOCK = threading.Lock()

# Saúde por provedor: usado pelo gate de pré-pagamento. Um provedor entra em
# quarentena após falhar e volta sozinho depois de _LLM_COOLDOWN segundos.
_LLM_COOLDOWN  = int(os.environ.get("LLM_COOLDOWN", "300"))
_LLM_DOWN_UNTIL: Dict[str, float] = {}
_LLM_LAST_ERROR: Dict[str, str] = {}
_LLM_STATE_LOCK = threading.Lock()


class LLMUnavailable(Exception):
    """Nenhum provedor de LLM respondeu. Quem levanta isto NÃO deve cobrar."""


# v39.4: HTTP 402/401 de um provedor não é falha transitória — é conta sem
# saldo ou chave revogada. Observado em produção:
#   LLM DeepSeek HTTP 402: {"error":{"message":"Insufficient Balance"}}
# A quarentena de 300s fazia o node insistir a cada 5 minutos, indefinidamente,
# numa conta que só volta quando ALGUÉM PAGA. Não é o node que resolve isso —
# é o operador. Então: quarentena longa e alerta específico, uma vez.
_BILLING_COOLDOWN = int(os.environ.get("LLM_BILLING_COOLDOWN", "21600"))  # 6 h
_BILLING_ALERTED: Dict[str, float] = {}


# v39.5: três tipos de falha, três tempos de espera. Num node de tier
# gratuito essa distinção é o que separa "usa a cota inteira" de "queima a
# cota em retries".
#   transitória  — timeout, 500, rate limit POR MINUTO. Volta em minutos.
#   cota diária  — TPD do Groq, RPD do Gemini. Só volta na virada do dia.
#   cobrança     — 402/401. Só volta se um humano agir.
_DAILY_COOLDOWN = int(os.environ.get("LLM_DAILY_COOLDOWN", "14400"))  # 4 h


def _is_daily_quota(detail: str) -> bool:
    d = (detail or "").lower()
    if "429" not in d and "resource_exhausted" not in d:
        return False
    return any(t in d for t in ("per day", "tpd", "rpd", "daily",
                                "requests per day", "tokens per day",
                                "quota", "resource_exhausted"))


def _is_billing_error(detail: str) -> bool:
    d = (detail or "").lower()
    return ("http 402" in d or "http 401" in d
            or "insufficient balance" in d or "insufficient_quota" in d
            or "quota exceeded" in d or "billing" in d
            or "invalid api key" in d or "incorrect api key" in d)


def _llm_mark(provider: str, ok: bool, detail: str = "") -> None:
    cobranca = (not ok) and _is_billing_error(detail)
    diaria = (not ok) and (not cobranca) and _is_daily_quota(detail)
    with _LLM_STATE_LOCK:
        if ok:
            _LLM_DOWN_UNTIL.pop(provider, None)
            _LLM_LAST_ERROR.pop(provider, None)
            _BILLING_ALERTED.pop(provider, None)
        else:
            espera = (_BILLING_COOLDOWN if cobranca
                      else _DAILY_COOLDOWN if diaria
                      else _LLM_COOLDOWN)
            _LLM_DOWN_UNTIL[provider] = time.time() + espera
            _LLM_LAST_ERROR[provider] = detail[:180]

    if diaria:
        log.warning(f"📅 {provider}: cota DIÁRIA esgotada — recuando "
                    f"{_DAILY_COOLDOWN // 3600}h em vez de "
                    f"{_LLM_COOLDOWN}s. Insistir a cada 5 min pelo resto do "
                    f"dia só gastaria requisições que já não existem.")

    if cobranca:
        # Alerta uma vez por janela — o operador precisa saber, mas não a cada
        # tentativa. Sem isto, a cadeia degrada em silêncio até cair inteira.
        agora = time.time()
        if agora - _BILLING_ALERTED.get(provider, 0) > _BILLING_COOLDOWN:
            _BILLING_ALERTED[provider] = agora
            log.error(f"💳 {provider}: erro de COBRANÇA, não de rede — "
                      f"{detail[:120]}. Em quarentena por "
                      f"{_BILLING_COOLDOWN // 3600}h; só volta se você repuser "
                      f"saldo ou trocar a chave.")
            try:
                _notify_telegram(
                    f"💳 *{provider}* fora por COBRANÇA, não por rede.\n\n"
                    f"`{detail[:150]}`\n\n"
                    f"Isso não se resolve sozinho — reponha saldo ou troque a "
                    f"chave. Quarentena de {_BILLING_COOLDOWN // 3600}h para "
                    f"não martelar a API.")
            except Exception:
                pass


def _llm_is_down(provider: str) -> bool:
    with _LLM_STATE_LOCK:
        return time.time() < _LLM_DOWN_UNTIL.get(provider, 0)


def llm_providers_configured() -> List[str]:
    out = []
    if DEEPSEEK_KEY: out.append("deepseek")
    if CLAUDE_KEY:   out.append("claude")
    if GROQ_KEY:     out.append("groq")
    if GEMINI_KEY:   out.append("gemini")
    if OLLAMA_ENABLED and OLLAMA_URL: out.append("ollama")
    return out


def llm_healthy() -> bool:
    """True se ao menos um provedor configurado não está em quarentena.
    É isto que o gate de pré-pagamento consulta antes de emitir um 402."""
    cfg = llm_providers_configured()
    if not cfg:
        return False
    return any(not _llm_is_down(p) for p in cfg)


def llm_health_report() -> dict:
    cfg = llm_providers_configured()
    with _LLM_STATE_LOCK:
        return {
            "configured": cfg,
            "healthy": bool(cfg) and any(time.time() >= _LLM_DOWN_UNTIL.get(p, 0)
                                         for p in cfg),
            "quarantined": {p: {"until": int(_LLM_DOWN_UNTIL[p]),
                                "last_error": _LLM_LAST_ERROR.get(p, "")}
                            for p in cfg if time.time() < _LLM_DOWN_UNTIL.get(p, 0)},
            "models": {"deepseek": DEEPSEEK_MODEL, "claude": CLAUDE_MODEL,
                       "groq": (groq_model() if GROQ_KEY else "(sem chave)"),
                       "gemini": GEMINI_MODEL or gemini_model()},
        }


# ---------------------------------------------------------------------------
# v39.5 — ROTEAMENTO PENSADO PARA TIER GRATUITO
#
# A cadeia da v39 era DeepSeek -> Claude -> Groq -> Gemini: ordem de quem PAGA
# pelo melhor modelo. Este node roda em tier gratuito, e aí a lógica é outra —
# a restrição não é qualidade, é COTA, e cada provedor tem uma cota diferente:
#
#   Groq   — rapidíssimo (~1s), mas o limite é TOKENS POR DIA. Os logs mostram
#            429 de TPD repetidamente. Cada prompt longo come uma fatia enorme
#            do orçamento diário.
#   Gemini — 2.5 Flash tem cota diária folgada e aceita respostas longas; é
#            mais lento, mas é o que aguenta volume.
#
# Então não faz sentido uma ordem fixa. Faz sentido rotear POR TAMANHO:
# pedido curto vai no Groq (rápido e barato em tokens), pedido longo vai no
# Gemini (onde o custo em tokens não derruba o dia inteiro). Assim o TPD do
# Groq é gasto em dezenas de chamadas pequenas em vez de três relatórios.
#
# LLM_ORDER=gemini,groq força uma ordem fixa se você preferir.
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# v39.6 — DESCOBERTA DE MODELO GEMINI EM TEMPO DE EXECUÇÃO
#
# Terceira vez que um modelo Gemini fixo no código morre em produção:
#   v38  gemini-2.0-flash-exp   -> 404, retirado
#   v39  gemini-2.5-flash       -> 404 "no longer available to new users"
# E não adianta olhar a documentação: o Google está aposentando modelos ANTES
# da data publicada de shutdown — a página de ciclo de vida ainda listava o
# 2.5 como disponível enquanto a API já recusava projetos novos.
#
# Chutar um quarto nome repetiria o erro. A própria mensagem de erro dá a
# saída: "Call ModelService.ListModels". Então perguntamos à API quais
# modelos ESTA chave pode usar, e escolhemos o melhor por preferência.
# Resultado: quando o Google aposentar o próximo, o node se conserta sozinho
# no próximo boot em vez de me esperar publicar um patch.
# ---------------------------------------------------------------------------
_GEMINI_RESOLVED: Optional[str] = None
_GEMINI_RESOLVED_AT = 0.0
_GEMINI_LOCK = threading.Lock()
GEMINI_DISCOVERY_TTL = int(os.environ.get("GEMINI_DISCOVERY_TTL", "21600"))  # 6 h

# Ordem de preferência por prefixo. Flash antes de Pro: cota gratuita maior e
# latência menor; "lite" por último, é o degrau de qualidade mais baixo.
# v47.3.0: nome FECHADO antes do alias "-latest". O gemini-flash-latest
# aponta sempre para o modelo mais disputado do free tier e vivia em
# 503/429 (quota) nos logs de ago/2026; o 2.5-flash tem cota própria
# documentada (1.500 RPD free) e bem menos concorrência. Aliases e lite
# ficam como último recurso, não como primeira escolha.
_GEMINI_PREF = ("2.5-flash", "3.5-flash", "3.1-flash", "3-flash",
                "flash", "flash-latest",
                "3.1-pro", "3-pro", "2.5-pro", "pro-latest", "flash-lite")


def _gemini_pick(nomes: List[str]) -> Optional[str]:
    """Escolhe o melhor modelo disponível segundo a ordem de preferência."""
    limpos = [n.replace("models/", "") for n in nomes]
    # Descarta variantes que não servem para texto simples.
    limpos = [n for n in limpos if not any(
        t in n for t in ("embedding", "aqa", "imagen", "veo", "tts",
                         "image", "audio", "vision", "learnlm", "gemma"))]
    for pref in _GEMINI_PREF:
        # v47.3.0: "lite" nunca casa por acidente com pref não-lite, e entre
        # candidatos do mesmo pref a versão estável ganha da "-preview".
        candidatos = [n for n in limpos
                      if pref in n and ("lite" not in n or "lite" in pref)]
        estaveis = [n for n in candidatos if "preview" not in n]
        if estaveis:
            return estaveis[0]
        if candidatos:
            return candidatos[0]
    return limpos[0] if limpos else None


def gemini_model() -> str:
    """Modelo a usar agora. Descobre uma vez e cacheia por GEMINI_DISCOVERY_TTL."""
    global _GEMINI_RESOLVED, _GEMINI_RESOLVED_AT
    # Override explícito ganha de tudo — para travar um modelo se preciso.
    fixo = os.environ.get("GEMINI_MODEL", "").strip()
    if fixo:
        return fixo
    with _GEMINI_LOCK:
        if _GEMINI_RESOLVED and (time.time() - _GEMINI_RESOLVED_AT) < GEMINI_DISCOVERY_TTL:
            return _GEMINI_RESOLVED
    if not GEMINI_KEY:
        return "gemini-flash-latest"
    try:
        r = requests.get(
            "https://generativelanguage.googleapis.com/v1beta/models",
            params={"key": GEMINI_KEY, "pageSize": 200}, timeout=12)
        if r.ok:
            todos = [m.get("name", "") for m in (r.json().get("models") or [])
                     if "generateContent" in (m.get("supportedGenerationMethods") or [])]
            escolhido = _gemini_pick(todos)
            if escolhido:
                with _GEMINI_LOCK:
                    _GEMINI_RESOLVED = escolhido
                    _GEMINI_RESOLVED_AT = time.time()
                log.info(f"🔎 Gemini: {len(todos)} modelos disponíveis para esta "
                         f"chave; usando '{escolhido}'")
                return escolhido
        log.warning(f"Gemini ListModels HTTP {r.status_code}: {r.text[:140]}")
    except Exception as e:
        log.warning(f"Gemini ListModels: {e}")
    # Sem descoberta: o alias 'latest' é o que menos envelhece.
    return "gemini-flash-latest"


# ---------------------------------------------------------------------------
# v47.1.0 — DESCOBERTA DE MODELO GROQ EM TEMPO DE EXECUCAO
#
# Mesma licao do Gemini (v39.6), agora para o Groq: modelo fixo morre sem
# aviso. A API /models devolve os modelos que ESTA chave pode usar; o node
# escolhe o melhor por preferencia e cacheia. Quando a Groq aposentar o
# proximo, o 400 de "decommissioned" limpa o cache e a proxima chamada ja
# vai com o modelo novo (ver _try_groq). Zero deploy, zero madrugada caido.
# ---------------------------------------------------------------------------
_GROQ_RESOLVED: Optional[str] = None
_GROQ_RESOLVED_AT = 0.0
_GROQ_LOCK = threading.Lock()
GROQ_DISCOVERY_TTL = int(os.environ.get("GROQ_DISCOVERY_TTL", "21600"))  # 6 h

# Raciocinio forte primeiro (gpt-oss-120b e o substituto oficial do
# llama-3.3-70b), depois alternativas rapidas/baratas. Filtra o que nao
# serve para chat de texto (audio, visao, guardas, embeddings).
_GROQ_PREF = ("gpt-oss-120b", "qwen3.6-27b", "qwen3-32b", "gpt-oss-20b",
              "llama-3.3", "llama-3.1", "llama", "qwen", "gpt-oss", "gemma")


def _groq_pick(ids: List[str]) -> Optional[str]:
    limpos = [i for i in ids if not any(
        t in i.lower() for t in ("whisper", "tts", "embed", "guard",
                                 "moderation", "orpheus", "vision", "audio",
                                 "playai", "compound"))]
    for pref in _GROQ_PREF:
        for i in limpos:
            if pref in i:
                return i
    return limpos[0] if limpos else None


def groq_model() -> str:
    """Modelo Groq a usar agora. Descobre 1x e cacheia por GROQ_DISCOVERY_TTL."""
    global _GROQ_RESOLVED, _GROQ_RESOLVED_AT
    fixo = os.environ.get("GROQ_MODEL", "").strip()
    if fixo:
        return fixo
    with _GROQ_LOCK:
        if _GROQ_RESOLVED and (time.time() - _GROQ_RESOLVED_AT) < GROQ_DISCOVERY_TTL:
            return _GROQ_RESOLVED
    if not GROQ_KEY:
        return "openai/gpt-oss-120b"
    try:
        r = requests.get("https://api.groq.com/openai/v1/models",
                         headers={"Authorization": f"Bearer {GROQ_KEY}"},
                         timeout=12)
        if r.ok:
            ids = [m.get("id", "") for m in (r.json().get("data") or [])]
            escolhido = _groq_pick(ids)
            if escolhido:
                with _GROQ_LOCK:
                    _GROQ_RESOLVED = escolhido
                    _GROQ_RESOLVED_AT = time.time()
                log.info("Groq: %d modelos disponiveis p/ esta chave; usando '%s'",
                         len(ids), escolhido)
                return escolhido
        log.warning(f"Groq ListModels HTTP {r.status_code}: {r.text[:140]}")
    except Exception as e:
        log.warning(f"Groq ListModels: {e}")
    return "openai/gpt-oss-120b"  # substituto oficial do llama-3.3-70b


def _groq_payload(modelo: str, prompt: str, max_tokens: int, temperature: float) -> dict:
    """v47.2.0: monta o pedido Groq a prova de reasoners.
    - piso de 512 tokens: gpt-oss/qwen3 raciocinam ANTES de responder; com
      max_tokens baixo (o probe usa 8!) o raciocinio come tudo e a resposta
      vem vazia com HTTP 200 — foi a queda silenciosa de 16/08.
    - reasoning_effort=low nos gpt-oss: resposta direta, sem queimar TPD."""
    p = {"model": modelo,
         "messages": [{"role": "user", "content": prompt}],
         "max_tokens": max(int(max_tokens), 512),
         "temperature": temperature}
    if "gpt-oss" in modelo:
        p["reasoning_effort"] = "low"
    return p


def _groq_esquece():
    """Zera o cache quando a API avisa que o modelo foi descomissionado."""
    global _GROQ_RESOLVED
    with _GROQ_LOCK:
        _GROQ_RESOLVED = None


LLM_SMALL_TOKENS = int(os.environ.get("LLM_SMALL_TOKENS", "300"))
_LLM_ORDER_ENV = [x.strip().lower() for x in
                  os.environ.get("LLM_ORDER", "").split(",") if x.strip()]


def _llm_chain(max_tokens: int) -> List[str]:
    """Ordem de tentativa para este pedido específico."""
    if _LLM_ORDER_ENV:
        return _LLM_ORDER_ENV
    pagos = [p for p in ("deepseek", "claude") if p in llm_providers_configured()]
    if max_tokens <= LLM_SMALL_TOKENS:
        gratis = ["groq", "gemini"]      # curto: Groq é mais rápido
    else:
        gratis = ["gemini", "groq"]      # longo: preserva o TPD do Groq
    # Provedores pagos, se configurados, vêm antes — quem paga quer qualidade.
    return pagos + gratis + ["ollama"]


class LLM:
    @staticmethod
    def _cache_get(key: str) -> Optional[str]:
        with _LLM_CACHE_LOCK:
            hit = _LLM_CACHE.get(key)
        if hit and (time.time() - hit[0]) < LLM_CACHE_TTL:
            return hit[1]
        return None

    @staticmethod
    def _cache_put(key: str, val: str) -> None:
        with _LLM_CACHE_LOCK:
            _LLM_CACHE[key] = (time.time(), val)
            if len(_LLM_CACHE) > 400:          # poda simples, sem dependências
                for k in sorted(_LLM_CACHE, key=lambda x: _LLM_CACHE[x][0])[:120]:
                    _LLM_CACHE.pop(k, None)

    @staticmethod
    def ask(prompt: str, max_tokens=512, temperature=0.4, cache=True) -> str:
        """Devolve texto do primeiro provedor que responder.
        String vazia significa 'nenhum provedor disponível' — nunca um
        placeholder que possa vazar para dentro de uma resposta paga."""
        # v41: força inglês na saída (ver LLM_FORCE_ENGLISH no topo).
        if LLM_FORCE_ENGLISH and "Respond ONLY in" not in prompt:
            prompt += LLM_ENGLISH_SUFFIX
        ck = ""
        if cache:
            ck = hashlib.sha256(
                f"{prompt}|{max_tokens}|{temperature}".encode()).hexdigest()
            hit = LLM._cache_get(ck)
            if hit is not None:
                return hit

        def _done(provider: str, text: str) -> str:
            _llm_mark(provider, True)
            text = (text or "").strip()
            if text and cache:
                LLM._cache_put(ck, text)
            return text

        def _try_deepseek():
            r = requests.post("https://api.deepseek.com/v1/chat/completions",
                headers={"Authorization": f"Bearer {DEEPSEEK_KEY}",
                         "Content-Type": "application/json"},
                json={"model": DEEPSEEK_MODEL,
                      "messages": [{"role": "user", "content": prompt}],
                      "max_tokens": max_tokens, "temperature": temperature},
                timeout=25)
            if r.ok:
                return r.json()["choices"][0]["message"]["content"], None
            return None, f"HTTP {r.status_code}: {r.text[:160]}"

        def _try_claude():
            r = requests.post("https://api.anthropic.com/v1/messages",
                headers={"x-api-key": CLAUDE_KEY,
                         "anthropic-version": "2023-06-01",
                         "Content-Type": "application/json"},
                json={"model": CLAUDE_MODEL,
                      "messages": [{"role": "user", "content": prompt}],
                      "max_tokens": max_tokens, "temperature": temperature},
                timeout=25)
            if r.ok:
                return r.json()["content"][0]["text"], None
            return None, f"HTTP {r.status_code}: {r.text[:160]}"

        def _try_groq():
            # v47.1.0: modelo descoberto em runtime + auto-recuperacao. Se a
            # Groq disser que o modelo foi descomissionado, zera o cache e
            # tenta UMA vez mais ja com o modelo recem-descoberto.
            for _tent in range(2):
                _gm = groq_model()
                r = requests.post("https://api.groq.com/openai/v1/chat/completions",
                    headers={"Authorization": f"Bearer {GROQ_KEY}",
                             "Content-Type": "application/json"},
                    json=_groq_payload(_gm, prompt, max_tokens, temperature),
                    timeout=25)
                if r.ok:
                    # v47.2.0: reasoners podem devolver content vazio quando o
                    # raciocinio come todo o orcamento. Se vier vazio, sobe o
                    # teto e tenta de novo UMA vez antes de desistir.
                    _txt = r.json()["choices"][0]["message"].get("content") or ""
                    if not _txt.strip() and max_tokens < 1024:
                        log.warning(f"Groq '{_gm}': resposta vazia com max_tokens={max_tokens}; retentando com folga")
                        r = requests.post("https://api.groq.com/openai/v1/chat/completions",
                            headers={"Authorization": f"Bearer {GROQ_KEY}",
                                     "Content-Type": "application/json"},
                            json=_groq_payload(_gm, prompt, 1024, temperature),
                            timeout=25)
                        if r.ok:
                            _txt = r.json()["choices"][0]["message"].get("content") or ""
                    return (_txt, None) if _txt.strip() else (None, "resposta vazia (reasoning comeu os tokens)")
                _corpo = r.text[:200].lower()
                if (r.status_code in (400, 404) and _tent == 0
                        and ("decommission" in _corpo or "model" in _corpo)):
                    log.warning(f"Groq: modelo '{_gm}' descomissionado — redescobrindo")
                    _groq_esquece()
                    continue
                # 429 aqui é quase sempre TPD (tokens por dia), não RPM.
                return None, f"HTTP {r.status_code}: {r.text[:160]}"
            return None, "modelo descomissionado e redescoberta falhou"

        def _try_gemini():
            _gm = gemini_model()          # v39.6: descoberto, não fixo
            # v47.2.0: os flash atuais "pensam" (thinking) antes de responder.
            # Com maxOutputTokens baixo o thinking consome tudo e o texto vem
            # vazio com HTTP 200 — mesma queda silenciosa do Groq. Piso de 512
            # e thinkingBudget=0 (flash) devolvem resposta direta.
            _cfg = {"maxOutputTokens": max(int(max_tokens), 512),
                    "temperature": temperature}
            if "flash" in _gm:
                _cfg["thinkingConfig"] = {"thinkingBudget": 0}
            r = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/"
                f"{_gm}:generateContent?key={GEMINI_KEY}",
                json={"contents": [{"parts": [{"text": prompt}]}],
                      "generationConfig": _cfg},
                timeout=25)
            if r.ok:
                j = r.json()
                cands = j.get("candidates") or []
                if not cands:
                    return None, f"no candidates: {str(j)[:120]}"
                parts = (cands[0].get("content") or {}).get("parts") or []
                if not parts:
                    # v39.5: MAX_TOKENS ou filtro de segurança devolvem
                    # candidato sem parts. Antes isso estourava IndexError e
                    # virava "exceção", escondendo a causa real.
                    return None, (f"empty parts, finishReason="
                                  f"{cands[0].get('finishReason')}")
                return parts[0].get("text", ""), None
            # Modelo retirado: limpa o cache para redescobrir na próxima.
            if r.status_code == 404:
                global _GEMINI_RESOLVED
                with _GEMINI_LOCK:
                    _GEMINI_RESOLVED = None
                log.warning(f"Gemini: modelo '{_gm}' retirado — redescobrindo")
            return None, f"HTTP {r.status_code} (modelo={_gm}): {r.text[:160]}"

        def _try_ollama():
            r = requests.post(f"{OLLAMA_URL}/api/generate",
                json={"model": OLLAMA_MODEL, "prompt": prompt, "stream": False,
                      "options": {"num_predict": max_tokens,
                                  "temperature": temperature}},
                timeout=30)
            if r.ok:
                return r.json().get("response", ""), None
            return None, f"HTTP {r.status_code}"

        _CHAMADAS = {"deepseek": (_try_deepseek, DEEPSEEK_KEY),
                     "claude":   (_try_claude,   CLAUDE_KEY),
                     "groq":     (_try_groq,     GROQ_KEY),
                     "gemini":   (_try_gemini,   GEMINI_KEY),
                     "ollama":   (_try_ollama,   OLLAMA_URL if OLLAMA_ENABLED else "")}

        for _prov in _llm_chain(max_tokens):
            _fn, _cred = _CHAMADAS.get(_prov, (None, None))
            if not _fn or not _cred or _llm_is_down(_prov):
                continue
            try:
                _txt, _err = _fn()
                if _txt:
                    return _done(_prov, _txt)
                _llm_mark(_prov, False, _err or "empty response")
                log.warning(f"LLM {_prov}: {_err}")
            except Exception as e:
                _llm_mark(_prov, False, str(e))
                log.warning(f"LLM {_prov}: {e}")

        # v39: nunca mais devolver um placeholder legível. A v38 devolvia
        # "[LLM offline — configure ...]" e essa string ia PARA DENTRO da
        # resposta paga de /analise e /relatorio. Vazio é honesto e o chamador
        # decide se ainda há produto a entregar.
        log.error("🚨 LLM indisponível em todos os provedores configurados")
        return ""

