    @staticmethod
    def onchain_credit():
        wallet = request.args.get("wallet", "").strip()
        # v21.11 FIX: comprador pagou $0.12 e recebia {"error": "missing valid
        # wallet"}. Índices de descoberta (B402 etc.) demovem sellers por fail
        # rate — erro pago é veneno duplo. Sem ?wallet=, o default inteligente
        # é pontuar a carteira do PRÓPRIO pagador (sabemos quem pagou!), com
        # fallback para um exemplo documentado. Nunca mais erro cru pago.
        if not wallet or len(wallet) < 32:
            from flask import g as _g
            payer_ctx = str(getattr(_g, "losbeto_payer", "") or "").strip()
            if payer_ctx and len(payer_ctx) >= 32 and not payer_ctx.startswith("0x"):
                wallet = payer_ctx
            else:
                wallet = RECEIVE_ADDRESS  # exemplo real e estável do próprio node
        txs = SOL.get_recent_txs(wallet, 50)
        balance = SOL.get_balance_usdc(wallet)
        oldest_ts = min((t.get("blockTime") or 0) for t in txs) if txs else int(time.time())
        age_days = (time.time() - oldest_ts) / 86400 if oldest_ts else 0
        score = min(900, int(300 + age_days * 2 + len(txs) * 4 + balance * 10))
        return {"wallet": wallet, "score": score,
                "age_days": round(age_days, 1),
                "tx_count_sample": len(txs),
                "usdc_balance": round(balance, 4),
                "tier": ("AAA" if score > 800 else "AA" if score > 650 else
                         "A" if score > 500 else "B" if score > 350 else "C"),
                "hint": "passe ?wallet=<endereco_solana> para pontuar qualquer carteira",
                "version": VERSION}

    @staticmethod
    def cross_chain():
        """v23: spreads REAIS — Binance × CoinGecko (CEX×referência) e
        Jupiter (DEX Solana). A v22 usava random.uniform() — dado fabricado
        em endpoint pago destrói reputação e fail-rate. Agora: fontes reais,
        metodologia declarada, honestidade como feature."""
        ts = int(time.time())
        out = {"opportunities": [],
               "sources": ["binance", "coingecko", "jupiter"],
               "methodology": ("spread CEX×referência (Binance vs CoinGecko) e "
                               "DEX Solana (Jupiter quote real). Indicativo — "
                               "não é cotação executável; slippage não incluído."),
               "ts": ts, "version": VERSION}
        try:
            cg = {(c.get("symbol") or "").upper(): c.get("current_price")
                  for c in Market.top_coins(10)}
            bn = {x["symbol"]: float(x.get("lastPrice", 0))
                  for x in (Market.binance_24h() or []) if x.get("symbol")}
            for sym, cg_price in cg.items():
                bp = bn.get(sym + "USDT")
                if cg_price and bp:
                    spread = (cg_price - bp) / bp * 100
                    if abs(spread) >= 0.10:
                        out["opportunities"].append({
                            "asset": sym, "type": "cex-reference",
                            "spread_pct": round(spread, 3),
                            "binance_usdt": bp, "coingecko_usd": cg_price,
                            "direction": ("buy binance → sell ref"
                                          if spread > 0 else "buy ref → sell binance"),
                        })
            # SOL DEX (Jupiter quote real) vs referência CoinGecko
            q = Market.jupiter_quote(USDC_MINT, WSOL_MINT, 100_000_000)  # 100 USDC → SOL
            sol_ref = cg.get("SOL")
            out_amt = (q or {}).get("outAmount")
            if out_amt and sol_ref:
                sol_dex = 100.0 / (int(out_amt) / 1e9)
                spread = (sol_dex - sol_ref) / sol_ref * 100
                out["opportunities"].append({
                    "asset": "SOL", "type": "dex-cex",
                    "spread_pct": round(spread, 3),
                    "jupiter_dex_usd": round(sol_dex, 4), "coingecko_usd": sol_ref,
                    "direction": ("buy ref → sell jupiter"
                                  if spread > 0 else "buy jupiter → sell ref"),
                })
            out["opportunities"].sort(key=lambda x: -abs(x["spread_pct"]))
            out["opportunities"] = out["opportunities"][:10]
            out["status"] = "live"
        except Exception as e:
            out["status"] = "degraded"
            out["note"] = str(e)
        return out

