    @staticmethod
    def launch_risk():
        """v21.17 FLAGSHIP — Launch Risk Brief: análise de risco de lançamento
        em tempo real. Funde pump_monitor (launches) + rugcheck on-chain
        (Helius) + liquidez/socials (DexScreener) + síntese LLM num veredicto
        acionável. Categoria com demanda real no x402 (memecoin tooling)."""
        ts = int(time.time())
        target = request.args.get("token", "").strip()

        # 1. Alvo: token informado, ou o launch mais recente com endereço Solana
        candidates = []
        if not target:
            for t in (Market.pump_new() or [])[:15]:
                addr = t.get("tokenAddress", "")
                if t.get("chainId") == "solana" and len(addr) >= 32:
                    candidates.append(t)
            if candidates:
                target = candidates[0]["tokenAddress"]
        if not target or len(target) < 32:
            return {"product": "launch-risk", "status": "no_target",
                    "hint": "passe ?token=<mint_solana> ou aguarde novos launches",
                    "ts": ts, "version": VERSION}

        checks, score = {}, 50  # 0 = seguro, 100 = fuja

        # 2. On-chain (Helius): autoridade de mint, mutabilidade
        try:
            if HELIUS_KEY:
                r = requests.post(
                    f"https://mainnet.helius-rpc.com/?api-key={HELIUS_KEY}",
                    json={"jsonrpc": "2.0", "id": 1, "method": "getAsset",
                          "params": {"id": target}}, timeout=8)
                if r.ok:
                    asset = r.json().get("result", {}) or {}
                    renounced = not bool(asset.get("authorities", []))
                    mutable = asset.get("mutable", True)
                    checks["mint_authority_renounced"] = renounced
                    checks["metadata_mutable"] = mutable
                    score += (-15 if renounced else 20) + (10 if mutable else -5)
        except Exception as e:
            log.warning(f"launch_risk helius: {e}")

        # 3. Concentração de holders (top-5)
        try:
            if HELIUS_KEY:
                r = requests.post(
                    f"https://mainnet.helius-rpc.com/?api-key={HELIUS_KEY}",
                    json={"jsonrpc": "2.0", "id": 1,
                          "method": "getTokenLargestAccounts",
                          "params": [target]}, timeout=8)
                vals = ((r.json().get("result") or {}).get("value") or []) if r.ok else []
                amounts = [float(v.get("uiAmount") or 0) for v in vals[:20]]
                if amounts and sum(amounts) > 0:
                    top5 = sum(amounts[:5]) / sum(amounts) * 100
                    checks["top5_holders_pct_of_top20"] = round(top5, 1)
                    score += 20 if top5 > 80 else (10 if top5 > 60 else -10)
        except Exception as e:
            log.warning(f"launch_risk holders: {e}")

        # 4. Liquidez + socials (DexScreener)
        pair_info = {}
        try:
            r = requests.get(
                f"https://api.dexscreener.com/latest/dex/tokens/{target}",
                timeout=8)
            pairs = (r.json().get("pairs") or []) if r.ok else []
            if pairs:
                p0 = max(pairs, key=lambda p: float((p.get("liquidity") or {}).get("usd") or 0))
                liq = float((p0.get("liquidity") or {}).get("usd") or 0)
                vol24 = float((p0.get("volume") or {}).get("h24") or 0)
                age_h = (ts - int(p0.get("pairCreatedAt", ts * 1000)) // 1000) / 3600
                socials = bool(((p0.get("info") or {}).get("socials")) or
                               ((p0.get("info") or {}).get("websites")))
                pair_info = {"dex": p0.get("dexId"), "pair": p0.get("pairAddress"),
                             "liquidity_usd": round(liq), "volume_24h_usd": round(vol24),
                             "age_hours": round(age_h, 1),
                             "price_usd": p0.get("priceUsd"),
                             "has_socials": socials,
                             "url": p0.get("url")}
                checks["liquidity_usd"] = round(liq)
                checks["has_socials"] = socials
                score += (25 if liq < 3000 else 10 if liq < 15000 else -15)
                score += (-5 if socials else 15)
                score += (10 if age_h < 1 else 0)
            else:
                checks["dexscreener_pair"] = "not_found"
                score += 15
        except Exception as e:
            log.warning(f"launch_risk dexscreener: {e}")

        score = max(0, min(100, score))
        verdict = ("EXTREME" if score >= 75 else "HIGH" if score >= 55
                   else "MEDIUM" if score >= 35 else "LOW")

        # 5. Síntese LLM (com fallback determinístico honesto)
        brief, brief_source = "", "rule-based"
        try:
            # v41: prompt em PT gerava brief em PT (visto na amostra do /try).
            prompt = (
                "You are a memecoin risk analyst. Based on the data below, "
                f"write a brief of AT MOST 4 sentences, direct and actionable, "
                f"in English, so a trading agent can decide in 5 seconds. "
                f"Data: token={target}, risk_score={score}/100 "
                f"(0=safe), checks={json.dumps(checks)}, pair={json.dumps(pair_info)}. "
                "End with a recommendation: AVOID / WATCH / SMALL-SIZE-ONLY.")
            out = LLM.ask(prompt, max_tokens=220, temperature=0.3)
            if out and "LLM offline" not in out:
                brief, brief_source = out, "llm"
        except Exception as e:
            log.warning(f"launch_risk llm: {e}")
        if not brief:
            brief = (f"Risk {score}/100 ({verdict}). "
                     + ("Mint authority NOT renounced. " if checks.get("mint_authority_renounced") is False else "")
                     + (f"Liquidity ${checks.get('liquidity_usd', 0):,}. " if "liquidity_usd" in checks else "")
                     + ("No socials found. " if checks.get("has_socials") is False else "")
                     + ("Recommendation: AVOID." if score >= 55 else
                        "Recommendation: WATCH." if score >= 35 else
                        "Recommendation: SMALL-SIZE-ONLY."))

        return {"product": "launch-risk-brief",
                "token": target,
                "risk_score": score,
                "verdict": verdict,
                "brief": brief,
                "brief_source": brief_source,
                "checks": checks,
                "pair": pair_info,
                "other_fresh_launches": [c.get("tokenAddress") for c in candidates[1:6]],
                "methodology": "On-chain checks (Helius) + DEX liquidity (DexScreener) + LLM synthesis. Heuristic, not financial advice.",
                "ts": ts, "version": VERSION}

    @staticmethod
    def council():
        """v21.20 — CONSELHO DOS CINCO: 5 IAs especializadas analisam o mercado
        em paralelo, cada uma com papel e dados próprios, e um Chairman sintetiza
        o veredicto com o placar de votos. Raro no x402."""
        ts = int(time.time())
        symbol = request.args.get("symbol", "SOL").upper()[:8]

        def _safe(fn, default):
            try: return fn()
            except Exception: return default

        AGENTS = [
            ("Sentinel",  "risco",      lambda: _safe(Market.fear_greed, {}),
             lambda d: "BEARISH" if (d.get("value") or 50) < 30 else "BULLISH" if (d.get("value") or 50) > 65 else "NEUTRAL"),
            ("Quant",     "regime",     lambda: _safe(Brain.regime, {}),
             lambda d: "BULLISH" if "bull" in str(d.get("regime","")) else "BEARISH" if "bear" in str(d.get("regime","")) else "NEUTRAL"),
            ("Scout",     "launches",   lambda: _safe(lambda: (Market.pump_new() or [])[:5], []),
             lambda d: "BULLISH" if len(d) >= 4 else "NEUTRAL" if len(d) >= 2 else "BEARISH"),
            ("Whale",     "liquidez",   lambda: _safe(Brain.defi_yield, {}),
             lambda d: "BULLISH" if d.get("top_yields") else "NEUTRAL"),
            ("Contrarian","sentimento", lambda: _safe(Brain.sentiment, {}),
             lambda d: {"BULLISH":"BEARISH","BEARISH":"BULLISH"}.get(str(d.get("sentiment","")).upper(), "NEUTRAL")),
        ]

        results, threads = {}, []
        import threading as _th
        def _run(name, role, collect, vote_fn):
            data = collect()
            stance = vote_fn(data)
            reason = ""
            try:
                out = LLM.ask(
                    f"You are {name}, the {role} specialist on a five-agent "
                    f"trading council. Data: "
                    f"{json.dumps(data, default=str)[:600]}. In ONE sentence, "
                    f"justify your {stance} stance on {symbol}, citing the "
                    f"single figure from the data that drives it.",
                    max_tokens=60, temperature=0.4)
                if out and "LLM offline" not in out: reason = out
            except Exception: pass
            results[name] = {"role": role, "vote": stance,
                             "reason": reason or f"rule-based {stance.lower()} signal from {role} data"}
        for a in AGENTS:
            t = _th.Thread(target=_run, args=a); t.start(); threads.append(t)
        for t in threads: t.join(timeout=25)

        votes = [r["vote"] for r in results.values()]
        tally = {v: votes.count(v) for v in ("BULLISH","NEUTRAL","BEARISH")}
        verdict = max(tally, key=tally.get)
        # v39: o "chairman synthesis" é exatamente o que o catálogo vende em
        # /council. Sem ele o produto vira uma contagem de votos heurísticos —
        # então falha alto e o decorador estorna, em vez de entregar menos.
        chairman = _ai_required(
            f"You are the Chairman of a five-agent AI trading council. Votes on "
            f"{symbol}: {json.dumps(results, default=str)[:900]}. Synthesise the "
            f"consensus and the suggested stance in exactly two sentences, in "
            f"English. This is not financial advice.",
            max_tokens=140)

        return {"product": "council-of-five", "symbol": symbol,
                "verdict": verdict, "tally": tally,
                "chairman_brief": chairman,
                "agents": results,
                "methodology": "Five specialised agents over live data, heuristic votes plus an LLM chairman synthesis. Not financial advice.",
                "ts": ts, "version": VERSION}

