# v44.4.0: nome de serviço alinhado ao fosso (<=32 chars, ASCII — regra Bazaar)
SERVICE_NAME = os.environ.get("SERVICE_NAME", "Losbeto Brazil Macro & Markets")[:32]

def _service_tags(endpoint: str) -> list:
    """v25: até 5 tags, cada uma <=32 chars ASCII imprimível (regra da spec).
    Derivadas das categorias reais + termos que um agente buscaria."""
    base_tags = [t.lower() for t in ENDPOINT_TAGS.get(endpoint, [])][:3]
    extra = []
    if endpoint in ("/forex-rate", "/forex-arbitrage"):
        extra = ["forex", "fx-rates"]
    elif endpoint in ("/stock-quote", "/equity-dossier", "/sector-rotation",
                      "/earnings-whisper"):
        extra = ["stocks", "equities"]
    elif endpoint in ("/commodity-price",):
        extra = ["commodities", "gold-oil"]
    elif endpoint in ("/macro-calendar", "/event-playbook", "/global-macro",
                      "/correlation-matrix"):
        extra = ["macro", "cross-asset"]
    else:
        extra = ["crypto", "market-data"]
    out, seen = [], set()
    for t in base_tags + extra:
        t = "".join(c for c in str(t) if 32 <= ord(c) <= 126)[:32]
        if t and t not in seen:
            seen.add(t)
            out.append(t)
    return out[:5]

def _bazaar_blob(endpoint: str) -> dict:
    """v25: formato EXATO da spec oficial do Bazaar (docs/extensions/bazaar.mdx).
    Três correções que os Seller Tools da agentic.market apontaram como faltantes:
      1. info.input.queryParams  -> valores CONCRETOS (era só method/type)
      2. info.output.example     -> amostra REAL do cache (era warning 'missing')
      3. inputSchema             -> era 'Input schema present: no'
    O schema legado (schema.properties.*) fica preservado para o validador
    @agentcash/discovery, que usa outro shape."""
    desc = ENDPOINT_DESC.get(endpoint, endpoint)
    params = dict(ENDPOINT_PARAM_HINTS.get(endpoint, {"format": "json"}))


    # exemplo de saída: dado real que o warmer já mantém quente (custo zero)
    example_out = {}
    try:
        cached = _PREVIEW_CACHE.get(endpoint) or _preview_db_get(endpoint)
        if cached:
            data = cached.get("data")
            if isinstance(data, dict):
                blob = json.dumps(data, default=str)
                if len(blob) <= 1200:
                    example_out = data
                else:  # recorta mantendo a forma
                    example_out, used = {}, 0
                    for k, v in data.items():
                        piece = json.dumps({k: v}, default=str)
                        if used + len(piece) > 1200:
                            continue
                        example_out[k] = v
                        used += len(piece)
    except Exception as e:
        log.debug(f"bazaar example {endpoint}: {e}")

    # v44.9.1: endpoints POST com corpo JSON (ex.: /v1/chat/completions) — o
    # blob padrão descreveria um GET com queryParams, e o x402scan avisava
    # "Paid endpoint is missing an input schema". Aqui o método e o schema
    # do corpo são declarados de verdade.
    _bs = ENDPOINT_BODY_SCHEMAS.get(endpoint) if "ENDPOINT_BODY_SCHEMAS" in globals() else None
    if _bs:
        return {
            "info": {
                "input": {"type": "http", "method": _bs["method"],
                          "contentType": _bs["contentType"],
                          "bodyParams": _bs["example"]},
                "output": ({"type": "json", "example": example_out} if example_out
                           else {"type": "json"}),
            },
            "inputSchema": _bs["schema"],
            "schema": {
                "$schema": "https://json-schema.org/draft/2020-12/schema",
                "type": "object",
                "properties": {
                    "input": {"type": "object", "properties": {
                        "method": {"type": "string", "description": _bs["method"]},
                        "bodyParams": _bs["schema"]}},
                    "output": {"type": "object", "properties": {
                        "example": {"type": "object", "description": desc}}},
                },
                "required": ["input"]},
            "description": desc,
            "title": endpoint.strip("/").replace("-", " ").title() + " — Losbeto",
            "tags": _service_tags(endpoint),
            "provider": {"name": SERVICE_NAME, "url": _public_base()},
        }
    props = {k: {"type": "string", "description": _PARAM_DESC.get(k, f"{k} parameter")}
             for k in params}
    return {
        "info": {
            "input": {"type": "http", "method": "GET", "queryParams": params},
            "output": ({"type": "json", "example": example_out} if example_out
                       else {"type": "json"}),
        },
        "inputSchema": {"type": "object", "properties": props, "required": []},
        # Shape legado exigido pelo validador @agentcash/discovery (extractSchemas2)
        "schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "type": "object",
            "properties": {
                "input": {"type": "object", "properties": {
                    "queryParams": {"type": "object", "properties": props}}},
                "output": {"type": "object", "properties": {
                    "example": {"type": "object", "description": desc}}},
            },
            "required": ["input"]},
        "description": desc,
        # v47.3.1: spec x402 v2 aceita title/tags/provider no bloco bazaar e
        # buscas por tag só casam com quem declara (docs Kobaru/Bazaar). É
        # aditivo — validadores antigos ignoram o que não conhecem.
        "title": endpoint.strip("/").replace("-", " ").title() + " — Losbeto",
        "tags": _service_tags(endpoint),
        "provider": {"name": SERVICE_NAME, "url": _public_base()},
    }

# ---------------------------------------------------------------------------
# v39 — CACHE DE DESAFIO (corrige uma venda perdida silenciosa)
#
# A v38 reconstruía o desafio no momento da liquidação:
#     accepts = _build_402(endpoint).get_json()["accepts"]
#     amount  = get_dynamic_price(endpoint)
# Como get_dynamic_price() aplica o multiplicador PoI, que muda a cada venda
# registrada, o preço podia MUDAR entre o 402 emitido e o pagamento chegar.
# O cliente assinou uma autorização para o valor antigo; o facilitator recebia
# requirements com o valor novo; verify() falhava e a venda se perdia sem
# nenhum log que apontasse a causa.
#
# Agora o desafio emitido é guardado por endpoint com TTL igual ao
# maxTimeoutSeconds do próprio desafio (300s). Na liquidação usamos o desafio
# EMITIDO, não um recalculado.
# ---------------------------------------------------------------------------
_CHALLENGE_CACHE: Dict[str, tuple] = {}
_CHALLENGE_LOCK = threading.Lock()
CHALLENGE_TTL = int(os.environ.get("CHALLENGE_TTL", "300"))


def _challenge_remember(endpoint: str, accepts: list) -> None:
    if not accepts:
        return
    with _CHALLENGE_LOCK:
        _CHALLENGE_CACHE[endpoint] = (time.time(), accepts)
        if len(_CHALLENGE_CACHE) > 300:
            for k in sorted(_CHALLENGE_CACHE,
                            key=lambda x: _CHALLENGE_CACHE[x][0])[:100]:
                _CHALLENGE_CACHE.pop(k, None)


def _challenge_recall(endpoint: str) -> Optional[list]:
    """Devolve os accepts realmente emitidos, se ainda dentro da janela."""
    with _CHALLENGE_LOCK:
        hit = _CHALLENGE_CACHE.get(endpoint)
    if hit and (time.time() - hit[0]) <= CHALLENGE_TTL:
        return hit[1]
    return None


# ---------------------------------------------------------------------------
# v39.7 — A OFERTA DE ASSINATURA VAI PARA DENTRO DO 402
#
# /pricing existe desde a v39.1 e nunca vendeu nada, por um motivo simples:
# nenhum agente visita uma página. O momento em que a decisão de compra
# acontece é EXATAMENTE quando o cliente recebe o 402 — ele está com a
# carteira na mão, avaliando se aquele preço vale. É ali que a alternativa
# precisa estar, não numa landing.
#
# Então todo desafio 402 passa a carregar um bloco "alternatives" dizendo, com
# número: quantas chamadas deste mesmo endpoint pagam um passe, e onde comprar.
# Um agente que planeja orçamento consegue decidir sem nenhuma chamada extra.
# ---------------------------------------------------------------------------

# v39.7 — GATILHO DE UPGRADE COM DADO REAL
# Dizer "assine" para quem fez uma chamada é spam. Dizer, para quem já gastou
# mais do que um passe custaria, exatamente quanto teria economizado, é
# informação — e é o argumento mais forte que existe, porque é o dinheiro dele.
_PAYER_SPEND: Dict[str, list] = {}
_PAYER_LOCK = threading.Lock()
UPSELL_WINDOW = int(os.environ.get("UPSELL_WINDOW", "86400"))  # 24 h


def _track_spend(payer: str, amount: float) -> None:
    if not payer or amount <= 0:
        return
    agora = time.time()
    with _PAYER_LOCK:
        hist = [x for x in _PAYER_SPEND.get(payer, []) if agora - x[0] < UPSELL_WINDOW]
        hist.append((agora, amount))
        _PAYER_SPEND[payer] = hist
        if len(_PAYER_SPEND) > 500:
            for k in list(_PAYER_SPEND)[:150]:
                _PAYER_SPEND.pop(k, None)


def _upsell_note(payer: str) -> Optional[dict]:
    """Só fala quando o número já favorece o cliente. Silêncio caso contrário."""
    if not payer:
        return None
    agora = time.time()
    with _PAYER_LOCK:
        hist = [x for x in _PAYER_SPEND.get(payer, []) if agora - x[0] < UPSELL_WINDOW]
    if len(hist) < 3:
        return None
    gasto = sum(a for _t, a in hist)
    # v39.7 — CORRIGIDO na verificação: a primeira versão recomendava o plano
    # mais barato que o cliente já tinha ultrapassado, e isso dava conselho
    # ERRADO. Quem gastou $3.15 ouvia "compre credits por $0.99" — mas credits
    # dá $1.25 de saldo e não teria coberto nem metade. Um upsell que não se
    # sustenta na conta do cliente é pior que nenhum upsell.
    #
    # Agora: o plano mais barato que REALMENTE teria coberto o gasto. Plano de
    # saldo cobre até balance_usd; plano ilimitado cobre qualquer valor.
    candidatos = sorted(
        ((BASE_PRICES[ep], ep, cfg) for ep, cfg in CREDIT_PLANS.items()
         if ep in BASE_PRICES), key=lambda x: x[0])
    for preco, ep, cfg in candidatos:
        cobertura = float("inf") if cfg["balance_usd"] == -1 else cfg["balance_usd"]
        if gasto > preco and cobertura >= gasto:
            economia = gasto - preco
            return {
                "you_spent_usdc": round(gasto, 4),
                "calls_in_window": len(hist),
                "window_hours": UPSELL_WINDOW // 3600,
                "plan": cfg["plan"],
                "plan_price_usdc": round(preco, 2),
                "would_have_saved_usdc": round(economia, 4),
                "buy": f"{_public_base()}{ep}",
                "message": (f"You have spent ${gasto:.4f} across {len(hist)} calls "
                            f"in the last {UPSELL_WINDOW // 3600}h. The "
                            f"{cfg['plan']} plan costs ${preco:.2f} and would "
                            f"have covered all of it with ${economia:.4f} left "
                            f"over — plus no settlement latency."),
            }
    return None


def _subscription_offer(endpoint: str, unit_price: float) -> Optional[dict]:
    """Alternativas mais baratas que pagar esta chamada avulsa, com o
    ponto de equilíbrio calculado no preço deste endpoint."""
    if unit_price <= 0 or endpoint in CREDIT_PLANS:
        return None
    base = _public_base()
    opcoes = []
    for ep, cfg in CREDIT_PLANS.items():
        preco = BASE_PRICES.get(ep)
        if not preco:
            continue
        ilimitado = cfg["balance_usd"] == -1
        equilibrio = int(preco / unit_price) + 1
        item = {
            "plan": cfg["plan"],
            "buy": f"{base}{ep}",
            "price_usdc": round(preco, 2),
            "duration_days": cfg["ttl_days"],
            "grants": ("unlimited calls to every endpoint" if ilimitado
                       else f"${cfg['balance_usd']:.2f} of call credit"),
            "breaks_even_after": equilibrio,
            "note": (f"Cheaper than paying per call from call #{equilibrio} "
                     f"onward, at this endpoint's price."),
        }
        if ilimitado:
            item["includes_mcp_live"] = True
        opcoes.append(item)
    opcoes.sort(key=lambda x: x["price_usdc"])
    return {
        "why": ("If your agent will call this more than a handful of times, "
                "one of these costs less and removes settlement latency "
                "entirely — the key is checked in about a millisecond instead "
                "of waiting for an on-chain confirmation."),
        "how_to_use": "Send the key you receive as the X-API-Key header.",
        "mcp": {"url": f"{base}/mcp",
                "header": "Authorization: Bearer <key>",
                "note": "A subscription turns the whole catalog into a live "
                        "MCP server for Claude Code, Cursor or any MCP client."},
        "plans": opcoes,
        "human_readable": f"{base}/pricing",
    }


def _build_402(endpoint: str):
    amount_usdc = get_dynamic_price(endpoint)
    amount_atomic_sol = str(int(amount_usdc * 10 ** USDC_DECIMALS))
    amount_atomic_base = str(int(amount_usdc * 10 ** 6))
    base = _public_base()
    desc = ENDPOINT_DESC.get(endpoint, f"Losbeto — {endpoint}")

    # extra.feePayer é OBRIGATÓRIO no scheme "exact" da SVM (Solana) — sem isso,
    # clientes x402 corretos (AgentCash, x402-fetch, etc.) rejeitam a payment requirement
    # com "feePayer is required in paymentRequirements.extra for SVM transactions".
    # v20: cadeia de fallback robusta.
    svm_extra = {}
    fee_payer = os.environ.get("SVM_FEE_PAYER_OVERRIDE", "").strip()
    if not fee_payer and FACILITATOR:
        fee_payer = FACILITATOR.get_svm_fee_payer()
    # v20: Último recurso — usa o próprio signer do node como feePayer (o cliente
    # ainda vai fechar a tx com um feePayer real do facilitator no momento do settle,
    # mas o campo não pode faltar senão o AgentCash rejeita antes de tentar).
    if not fee_payer:
        fee_payer = WALLET.solana_address
    if fee_payer:
        svm_extra["feePayer"] = fee_payer

    _sol_accept = {
        "scheme":            "exact",
        "network":           f"solana:{SOL_GENESIS}",
        "asset":             USDC_MINT,
        "amount":            amount_atomic_sol,
        "payTo":             RECEIVE_ADDRESS,
        "maxTimeoutSeconds": 300,
        "extra":             svm_extra,
    }
    accepts = []
    if PREFER_BASE and ENABLE_BASE and BASE_PAYTO_EVM:
        # v25.1: ordem dos accepts DECIDE a descoberta. Clientes x402 escolhem
        # tipicamente accepts[0]; com Solana em 1º, os settles iam para o PayAI
        # e NUNCA passavam pela CDP — e só a CDP cataloga no Bazaar (por isso
        # apenas 5 dos 67 endpoints estavam indexados). Base primeiro = cada
        # venda vira uma entrada de catálogo. Solana continua aceita em 2º.
        pass  # Base é inserida logo abaixo; Solana é anexada depois
    else:
        accepts.append(_sol_accept)
    if ENABLE_BASE and BASE_PAYTO_EVM:
        accepts.append({
            "scheme":            "exact",
            "network":           BASE_CAIP2,
            "asset":             BASE_USDC,
            "amount":            amount_atomic_base,
            "payTo":             BASE_PAYTO_EVM,
            "maxTimeoutSeconds": 300,
            # v21.10 FIX: USDC em Base usa EIP-3009 (transferWithAuthorization);
            # o cliente PRECISA do domínio EIP-712 (name/version do contrato)
            # para assinar. Sem isso, TODO pagamento via Base falha no cliente:
            # "EIP-712 domain parameters (name, version) are required".
            "extra":             {"name": "USD Coin", "version": "2"},
        })
    if PREFER_BASE and ENABLE_BASE and BASE_PAYTO_EVM:
        accepts.append(_sol_accept)      # Solana segue disponível, em 2ª opção
    if ENABLE_ALGO:
        # v44.7.0-ALGORAND: 3ª opção de pagamento — USDC na Algorand mainnet
        # (ASA 31566704, 6 casas decimais como Base/Solana) via GoPlausible.
        # Requisito oficial do Global x402 Challenge: campo 'tag' dentro do
        # extra. Posição 3 proposital: Base continua 1ª (indexação CDP/Bazaar)
        # e Solana 2ª — Algorand soma, não canibaliza as rails que já rankeiam.
        accepts.append({
            "scheme":            "exact",
            "network":           ALGO_CAIP2,
            "asset":             ALGO_USDC_ASA,
            "amount":            amount_atomic_base,
            "payTo":             ALGO_PAYTO,
            "maxTimeoutSeconds": 300,
            "extra":             {"feePayer": ALGO_FEEPAYER,
                                  "tag": "x402-global-challenge"},
        })
    # v21 FIX: payload compatível com x402scan — campos da spec v2 + challenges
    payment_req = accepts[0] if accepts else {}
    _challenge_remember(endpoint, accepts)   # v39: usado na liquidação
    payload = {
        "x402Version": 2,
        "resource": {
            "url":         f"{base}{endpoint}",
            "description": desc,
            "mimeType":    "application/json",
            # v25: Service Metadata da spec oficial do Bazaar — facilitators usam
            # estes campos para enriquecer os resultados de BUSCA com nome legível,
            # tags temáticas e ícone. Regras: serviceName/tags só ASCII imprimível
            # (<=32 chars cada, máx 5 tags); iconUrl absoluto https.
            "serviceName": SERVICE_NAME,
            "tags":        _service_tags(endpoint),
            "iconUrl":     f"{base}/favicon.png",
        },
        "accepts":    accepts,
        # v39.7: a alternativa mais barata, no momento exato da decisão.
        "alternatives": _subscription_offer(endpoint, amount_usdc),
        # v47.6.3 (parceria stipend.sh): agente SEM carteira recebe o caminho
        # para se equipar sozinho. JSON estático — nada chama casa, nenhum
        # beacon. A 3ª linha é deliberada: qualquer carteira EIP-3009 serve.
        "no_wallet": {
            "install": "npx -y stipend",
            "docs":    "https://stipend.sh/skill.md",
            "any_wallet_works": "You do not need this one. Any address that "
                                "can sign an EIP-3009 authorisation on Base "
                                "works here.",
        },
        # v1 backward compat: alguns scanners (x402scan legacy) esperam paymentRequirements
        "paymentRequirements": {
            "scheme":            payment_req.get("scheme", "exact"),
            "network":           payment_req.get("network", f"solana:{SOL_GENESIS}"),
            "asset":             payment_req.get("asset", USDC_MINT),
            "maxAmountRequired": payment_req.get("amount", "0"),
            "payTo":             payment_req.get("payTo", RECEIVE_ADDRESS),
            "maxTimeoutSeconds": payment_req.get("maxTimeoutSeconds", 300),
        } if payment_req else None,
        # challenges: formato alternativo que alguns scanners esperam
        "challenges": [{
            "scheme": acc.get("scheme", "exact"),
            "network": acc.get("network", f"solana:{SOL_GENESIS}"),
            "asset": acc.get("asset", USDC_MINT),
            "amount": acc.get("amount", "0"),
            "payTo": acc.get("payTo", RECEIVE_ADDRESS),
            "maxTimeoutSeconds": acc.get("maxTimeoutSeconds", 300),
        } for acc in accepts],
        # v21.4 FIX: extensions DEVE ser objeto ({}), nunca null — o PayAI rejeita
        # com "extensions: Invalid input: expected record, received null" porque o
        # cliente (AgentCash) ecoa esse campo no PaymentPayload que envia de volta.
        "extensions": {"bazaar": _bazaar_blob(endpoint)},
        # v23.2: todo 402 é uma vitrine — agente sem saldo sai com um caminho
        "upsell": {
            # v24.6: AMOSTRA EMBUTIDA — o achado da telemetria: 6.000 sondagens/dia
            # e ZERO usos do ?preview=1. Scanners não fazem segunda chamada. Então
            # a amostra agora viaja DENTRO do 402: o agente vê a forma real do dado
            # na mesma resposta em que descobre o preço. Zero requests extras.
            "sample": _inline_sample(endpoint),
            "free_preview": {
                "endpoint": f"{base}{endpoint}?preview=1",
                "cost": "0.00",
                "note": "Same resource, real data delayed ~15min. Evaluate before paying."},
            "try_free": [f"{base}{endpoint}?preview=1", f"{base}/try", f"{base}/sample",
                         f"{base}/losbeto-alpha", f"{base}/receipts"],
            # v41: A PONTE QUE FALTAVA ENTRE AVALIAR E PAGAR.
            # O funil real mostra ~10-20 avaliações/dia (python-requests) que
            # veem a amostra ATRASADA e somem. Amostra atrasada prova que o
            # node está vivo, mas não prova o valor do real-time. Uma chamada
            # REAL de graça (custo marginal ~$0 nos endpoints de dados) é o
            # trial que todo SaaS de API tem — e o x402 não tinha.
            "first_call_free": {
                "endpoint": f"{base}/welcome",
                "cost": "0.00",
                "note": ("One FREE real-time call, no payment and no signup. "
                         "GET /welcome, then send the returned token as the "
                         "X-Welcome-Token header to any whitelisted endpoint.")},
            "tasting_menu": {"endpoint": f"{base}/try", "cost": "0.00",
                             "note": "One free call = live samples from 6 endpoints."},
            "cheapest_paid": _cheapest_paid(base),
            "credits": {"endpoint": f"{base}/buy-credits",
                        "deal": "$1 -> $1.25 balance, zero settlement latency"},
            "docs": f"{base}/llms.txt"},
    }
    # v21 FIX: base64 padrão (não URL-safe) — scanners usam b64decode padrão.
    # v25 FIX CRÍTICO: NÃO remover o padding "=". A spec x402 v2 exige o payload
    # PaymentRequired em base64 canônico no header PAYMENT-REQUIRED; sem padding,
    # b64decode() estrito falha com "Incorrect padding" em ~75% dos endpoints
    # (todo payload cujo tamanho não é múltiplo de 3). Isso quebrava a leitura
    # do desafio por clientes/facilitators que seguem a spec à risca — e explica
    # a extensão bazaar chegar VAZIA ({}) no catálogo da CDP.
    # v28.1 FIX CRÍTICO: o CORPO leva tudo; o HEADER leva uma versão enxuta.
    # Diagnóstico: a resposta 402 chegou a 19.627 bytes de cabeçalhos
    # (WWW-Authenticate 6.2k + PAYMENT-REQUIRED 6k + X-PAYMENT-REQUIRED 6k
    # duplicado). Node.js aborta acima de 16 KB e proxies cortam em 8 KB —
    # por isso clientes Node (AgentCash) recebiam NETWORK_ERROR em TODO
    # endpoint pago, enquanto os gratuitos funcionavam. Zero pagamentos em 24h.
    # Solução: amostra embutida e exemplos do bazaar ficam só no corpo.
    def _slim(p: dict) -> dict:
        """Versão do desafio para o CABEÇALHO: só o que um cliente precisa
        para pagar. Marketing, amostras e duplicatas ficam no corpo."""
        import copy
        ext = copy.deepcopy((p.get("extensions") or {}).get("bazaar") or {})
        info_out = (ext.get("info") or {}).get("output") or {}
        info_out.pop("example", None)   # exemplo de saída: grande, vai no corpo
        ext.pop("schema", None)         # schema legado: idem
        # v34: descrição TRUNCADA no cabeçalho. O pior caso chegou a 7.373 bytes
        # (90% do limite de 8 KB) por causa de descrições longas. O texto integral
        # continua no corpo e nos manifests; no header basta o suficiente para o
        # cliente saber o que está comprando.
        _res = dict(p.get("resource") or {})
        if isinstance(_res.get("description"), str) and len(_res["description"]) > 220:
            _res["description"] = _res["description"][:217].rstrip() + "..."
        _ext_desc = ext.get("description")
        if isinstance(_ext_desc, str) and len(_ext_desc) > 220:
            ext["description"] = _ext_desc[:217].rstrip() + "..."
        return {
            "x402Version": p.get("x402Version", 2),
            "resource":    _res,
            "accepts":     p.get("accepts"),
            # compat v1: alguns scanners antigos leem este campo
            "paymentRequirements": p.get("paymentRequirements"),
            "extensions":  {"bazaar": ext},
            # "challenges" (cópia de accepts) e "upsell" (amostra, try_free,
            # créditos, docs) permanecem apenas no CORPO — não são necessários
            # para executar o pagamento e custavam ~2 KB de cabeçalho.
        }
    # v39.1: o registro no x402scan avisou "Paid endpoint is missing an input
    # schema" em todos os endpoints com parâmetro. O schema alimenta a busca
    # semântica dos diretórios e diz ao agente COMO chamar sem tentativa e erro.
    _hints = ENDPOINT_PARAM_HINTS.get(endpoint, {})
    _props = {k: {"type": "string",
                  "description": _PARAM_DESC.get(k, f"{k} parameter"),
                  "example": v}
              for k, v in _hints.items() if k != "format"}
    # v44.9.1: endpoints POST declaram o schema do CORPO (não queryParams) —
    # era o warning "missing an input schema" do registro no x402scan.
    _bs402 = ENDPOINT_BODY_SCHEMAS.get(endpoint) if "ENDPOINT_BODY_SCHEMAS" in globals() else None
    if _bs402:
        payload["inputSchema"] = _bs402["schema"]
        payload["inputMethod"] = _bs402["method"]
        payload["inputContentType"] = _bs402["contentType"]
        payload["inputExample"] = _bs402["example"]
    else:
        payload["inputSchema"] = {
            "type": "object",
            "properties": _props,
            "required": [],
            "additionalProperties": False,
        }
    payload["outputSchema"] = {"type": "object", "mimeType": "application/json"}

    payload_hdr = _slim(payload)
    b64 = base64.b64encode(
        json.dumps(payload_hdr, separators=(",", ":")).encode()
    ).decode()
    resp = jsonify(payload)            # corpo: payload COMPLETO
    resp.status_code = 402
    # v21.1 FIX: além do blob base64 opaco (challenge="..."), expõe os campos reais
    # do desafio de pagamento como auth-params legíveis (RFC 9110 §11.3), no formato
    # que scanners como o x402scan procuram ("no Payment challenges" era esse warning).
    primary = accepts[0] if accepts else {}
    # v28.1: o challenge base64 NÃO vai aqui — ele já está em PAYMENT-REQUIRED.
    # Repetir o blob triplicava o tamanho dos cabeçalhos.
    # v34 FIX — REGRESSÃO INTRODUZIDA NA v28.1.
    # Ao enxugar os cabeçalhos de 19,6 KB, removi o `challenge="<b64>"` do
    # WWW-Authenticate. Resultado: o registro no x402scan passou a avisar
    # "WWW-Authenticate header contains no Payment challenges" em 70 dos 79
    # recursos — exatamente o aviso que a v21.1 havia eliminado.
    # Correção: challenge volta, mas COMPACTO. O blob completo (~4,8 KB) fica
    # só em PAYMENT-REQUIRED; aqui vai o mínimo que um cliente precisa para
    # pagar: versão + accepts essenciais. ~500 bytes em vez de 6 KB.
    _min_accepts = [{k: a[k] for k in
                     ("scheme", "network", "asset", "amount", "payTo", "maxTimeoutSeconds")
                     if k in a} for a in accepts]
    _chal = base64.b64encode(json.dumps(
        {"x402Version": 2, "accepts": _min_accepts},
        separators=(",", ":")).encode()).decode()
    auth_params = [f'realm="x402"', f'challenge="{_chal}"']
    if primary:
        for k in ("scheme", "network", "asset", "amount", "payTo", "maxTimeoutSeconds"):
            v = primary.get(k)
            if v is not None:
                auth_params.append(f'{k}="{v}"')
    resp.headers["WWW-Authenticate"] = "x402 " + ", ".join(auth_params)
    # v42 — SEGUNDO challenge, no shape MPP (RFC 7235 permite N challenges).
    # O validador da agentic.market/x402scan/MPPScan procura um auth-scheme
    # "Payment"; sem ele, TODOS os 74 endpoints apareciam com warning no
    # registro. O desafio x402 continua primeiro (compat total); este apenas
    # descreve o MESMO pagamento no vocabulário MPP (charge intent mapeia
    # direto o fluxo "exact" do x402 — é o que a spec chama de backward-compat).
    if MPP_CHALLENGE:
        resp.headers.add("WWW-Authenticate", _mpp_challenge(endpoint, primary))
    resp.headers["PAYMENT-REQUIRED"]   = b64
    # v28.1: era uma cópia byte a byte de PAYMENT-REQUIRED (+6 KB à toa).
    # Mantido só se couber no orçamento total de cabeçalhos.
    if len(b64) <= 2048:
        resp.headers["X-PAYMENT-REQUIRED"] = b64
    else:
        resp.headers["X-Payment-Required-Ref"] = "see PAYMENT-REQUIRED header"
    # v24.5: cliente que só lê headers (muitos agentes) também descobre o preview
    resp.headers["X-Free-Preview"] = f"{base}{endpoint}?preview=1"
    resp.headers["X-402-Version"]      = "1,2"
    resp.headers["X-Node-Id"]          = WALLET.node_id
    resp.headers["X-Accept-Chains"]    = ",".join([a["network"] for a in accepts])
    # Link header para discovery legacy (Web Monetization / ILP compat)
    resp.headers["Link"] = (f'<{base}{endpoint}?preview=1>; rel="preview"; type="application/json", '
                            f'<{base}/.well-known/x402.json>; rel="payment"')
    # Accept-Payment header para compatibilidade com draft specs
    resp.headers["Accept-Payment"] = f'x402; networks={",".join(a["network"] for a in accepts)}'
    # v41: agentes que rodam em browser (fetch/XHR) não conseguem LER o
    # PAYMENT-REQUIRED sem CORS expose — o desafio existia mas era invisível
    # para clientes web (metade das avaliações diárias são navegadores).
    resp.headers["Access-Control-Expose-Headers"] = (
        "PAYMENT-REQUIRED,X-PAYMENT-REQUIRED,WWW-Authenticate,X-Free-Preview,"
        "X-402-Version,X-Accept-Chains")
    return resp

def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()

def _ascii_header(s: str) -> str:
    """v42.1 FIX CRÍTICO: valores de header HTTP devem ser ASCII (RFC 7230).
    ENDPOINT_DESC tem tipografia rica (—, ·, ç, ã) — quando o travessão caía
    nos primeiros 90 chars, o challenge MPP saía com byte não-ASCII e clients
    HTTP estritos (httpx, Node undici) ABORTAVAM a request ao ecoar o valor.
    Foi o que derrubou 6 endpoints no Agentic.Market ([502] 'No valid x402
    response found') e inundou o gunicorn com 'Invalid HTTP Header' — todos
    os 6 tinham U+2014 dentro da janela de 90 chars; os endpoints com — depois
    do char 90 passavam pela truncagem. Coincidência perfeita, bug real."""
    s = (s or "").replace("—", "-").replace("–", "-").replace("·", "|")
    return s.encode("ascii", "ignore").decode("ascii")

def _mpp_challenge(endpoint: str, primary: dict) -> str:
    """v42: challenge no formato MPP (IETF draft-httpauth-payment-00).
    id vinculado aos termos (endpoint+valor+payTo, janela de 5 min) — o mesmo
    padrão stateless da spec; request em base64url com o mapeamento charge→exact:
    amount atômico, moeda, destinatário, rede e asset. Clients MPP reconhecem o
    auth-scheme "Payment" e validadores deixam de marcar o endpoint com warning.

    LIMITAÇÃO DECLARADA (v42.1): method="x402" não é um payment method MPP
    registrado — a spec é agnóstica e métodos são definidos em specs separadas.
    Este challenge satisfaz scanners de diretório (X402Scan/MPPScan/Agentic.
    Market) e documenta os termos num formato legível; o fluxo MPP completo
    (Credential/Receipt) NÃO é implementado. Um client MPP bem-comportado
    ignora métodos desconhecidos e cai no challenge x402 ao lado — que é o
    caminho real de pagamento. Se um dia existir method spec x402 registrada,
    basta implementar o handshake aqui."""
    base = _public_base()
    atomic = str(primary.get("amount") or primary.get("maxAmountRequired") or "0")
    req = {"amount": atomic,
           "currency": "USDC",
           "recipient": primary.get("payTo", ""),
           "network": primary.get("network", ""),
           "asset": primary.get("asset", ""),
           "resource": f"{base}{endpoint}",
           "protocol": "x402-exact"}
    blob = _b64url(json.dumps(req, separators=(",", ":"), sort_keys=True).encode())
    cid = hashlib.sha256(
        f"mpp|{endpoint}|{atomic}|{primary.get('payTo')}|{int(time.time() // 300)}"
        .encode()).hexdigest()[:20]
    desc = _ascii_header(ENDPOINT_DESC.get(endpoint, endpoint) or "")[:90].replace('"', "'")
    exp = datetime.fromtimestamp(time.time() + 300, timezone.utc
                                 ).strftime("%Y-%m-%dT%H:%M:%SZ")
    return (f'Payment id="{cid}", realm="losbeto", method="x402", intent="charge", '
            f'request="{blob}", expires="{exp}", description="{desc}"')

def _verify_payment(endpoint: str, payment_header: str):
    if not payment_header:
        return False, "missing-header", {}
    payment_header = payment_header.strip()
    # v21: aceita header raw (v1 sig direto) OU base64 JSON (v2 payload completo)
    h = hashlib.sha256(payment_header.encode()).hexdigest()
    # v23 FIX CRÍTICO: a v22 gravava o hash ANTES de verificar. Qualquer falha
    # transitória (tx-not-found por lag de RPC, 5xx do facilitator) deixava o
    # hash preso → o retry legítimo do cliente voltava "replay-blocked" e a
    # venda morria na linha de chegada. Agora: checa antes, marca só no settle.
    if LEDGER.replay_seen(h):
        return False, "replay-blocked", {}
    tx_sig = payment_header
    payer  = ""
    network = "solana"
    payload = {}
    last_reason = ""   # v44.2.2: motivo do facilitador, devolvido no 402
    fac_reasons = {}   # v44.2.2: um motivo por facilitador (dedup entre accepts)
    try:
        decoded = base64.b64decode(payment_header).decode()
        pdata = json.loads(decoded)
        payload = pdata
        if "payload" in pdata:
            inner = pdata["payload"]
            tx_sig = inner.get("signature") or inner.get("transaction") or inner.get("tx") or tx_sig
            payer  = inner.get("payer") or inner.get("from") or ""
        else:
            tx_sig = pdata.get("signature") or pdata.get("tx") or payment_header
            payer  = pdata.get("payer", "")
        network = pdata.get("network", "solana")
        # v44.2.3 FIX CRÍTICO — a rede do payload v2 mora em accepted.network.
        # O SDK oficial v2 NÃO repete scheme/network no topo do PaymentPayload
        # (só {x402Version, payload, resource, accepted}). Sem este fallback,
        # um pagamento Base v2 caía no default "solana": o v21.5/v24.9 deixava
        # o accept SOLANA ser verificado contra o payload EVM → o facilitator
        # respondia "network_mismatch" e esse motivo-fantasma sobrescrevia o
        # motivo REAL da tentativa correta (eip155) no 402 devolvido.
        if isinstance(pdata.get("accepted"), dict) and pdata["accepted"].get("network"):
            network = pdata["accepted"]["network"]
    except Exception:
        tx_sig = payment_header.strip()

    # v39: o valor registrado é o que foi efetivamente cotado ao cliente.
    _quoted = _challenge_recall(endpoint)
    if _quoted:
        try:
            amount = int(_quoted[0]["amount"]) / (10 ** USDC_DECIMALS)
        except Exception:
            amount = get_dynamic_price(endpoint)
    else:
        amount = get_dynamic_price(endpoint)
    # v44.8.2: Algorand caía no else e ia pro ledger como "solana" — receipts
    # com txid AVM e link solscan quebrado. Detecta as 3 chains explicitamente.
    _net_l = str(network).lower()
    chain = ("algorand" if _net_l.startswith("algorand")
             else "base" if ("eip155" in _net_l or _net_l.startswith("base") or str(tx_sig).startswith("0x"))
             else "solana")

    if (FACILITATOR or CDP_FAC) and payload:
        # v21.4 FIX: sanitiza campos-objeto que cheguem como null no payload do
        # cliente — o schema do PayAI exige record ({}), e null causa 400.
        for _k in ("extensions", "extra"):
            if _k in payload and payload[_k] is None:
                payload[_k] = {}
        if isinstance(payload.get("payload"), dict):
            for _k in ("extensions", "extra"):
                if _k in payload["payload"] and payload["payload"][_k] is None:
                    payload["payload"][_k] = {}
        # v39: prefere o desafio EMITIDO ao recalculado — ver _CHALLENGE_CACHE.
        accepts = _challenge_recall(endpoint)
        if accepts is None:
            accepts = _build_402(endpoint).get_json()["accepts"]
        else:
            _issued = accepts[0].get("amount") if accepts else None
            _now_amt = str(int(get_dynamic_price(endpoint) * 10 ** USDC_DECIMALS))
            if _issued and _issued != _now_amt:
                log.info(f"💱 {endpoint}: preço mudou entre desafio e liquidação "
                         f"({_issued} → {_now_amt}); honrando o valor cotado.")
        # v21.5 FIX: só envia ao facilitator o accept cuja network bate com a do
        # payload do cliente. Verificar payload Solana contra requirements Base
        # (e vice-versa) é um combo inválido que pode causar 500 no facilitator.
        # v44.2.3: rede efetiva do cliente — v1 no topo, v2 em accepted.network
        # (a variável `network` já saiu do parse com esse fallback aplicado).
        pay_net = str(payload.get("network")
                      or (payload.get("accepted") or {}).get("network")
                      or network or "")
        matched = [a for a in accepts if str(a.get("network", "")) == pay_net]
        ordered = matched if matched else accepts
        # v21.6 DEFINITIVO (formato extraído do SDK oficial x402/PayAI):
        # PaymentRequirements v2 = {scheme, network, asset, amount, payTo,
        # maxTimeoutSeconds, extra}. NÃO usar maxAmountRequired/resource/
        # description/mimeType (isso é v1 e quebra o code path v2 → 500).
        # Melhor ainda: o PaymentPayload v2 traz "accepted" = o requirement
        # exato que o cliente usou pra montar a transação. Usá-lo garante
        # consistência total. Fallback: nosso accept cru (mesma shape v2).
        candidates = []
        client_accepted = payload.get("accepted")
        if isinstance(client_accepted, dict) and client_accepted.get("scheme"):
            if client_accepted.get("extra") is None:
                client_accepted["extra"] = {}
            candidates.append(client_accepted)
        candidates.extend(ordered)
        last_reason = "no-accepts"
        tried = set()
        for req in candidates:
            _key = json.dumps(req, sort_keys=True, default=str)
            if _key in tried:
                continue
            tried.add(_key)
            # v24.9: só tenta accepts da MESMA rede em que o cliente assinou.
            # Antes, um pagamento Solana era reenviado ao facilitator da CDP
            # (só EVM) → 'preflight_validation_failed', 30s de timeout gastos
            # segurando uma thread do gunicorn e o blob da tx indo pro log.
            # v44.2.3: payload v2 não repete network no topo — olha accepted.
            _payload_net = str((payload or {}).get("network")
                               or ((payload or {}).get("accepted") or {}).get("network")
                               or (payload or {}).get("chain") or "")
            _req_net = str(req.get("network", ""))
            if _payload_net and _req_net and _payload_net != _req_net:
                log.debug(f"skip accept {_req_net} (cliente pagou em {_payload_net})")
                continue
            # v21.13: roteamento por rede — Base vai pra CDP (indexa no Bazaar),
            # Solana continua no PayAI. Fallback: facilitator principal.
            # v44.2.1: se a CDP recusar um pagamento EVM, tenta o facilitador
            # principal (PayAI) como contingência ANTES de desistir da venda
            # (ver flag CDP_FALLBACK_PAYAI no topo). `fac` guarda quem de fato
            # verificou — settle, bazaar blob e resource seguem esse mesmo `fac`,
            # então blob/resource da CDP só vão quando a CDP liquidou.
            # v44.3.3: disjuntor aberto = CDP fora da cadeia (venda vai direto
            # ao PayAI, sem o ~1s perdido nem o WARNING por request).
            if CDP_FAC and _req_net.startswith("eip155") and _cdp_available():
                facs = [CDP_FAC]
                if FACILITATOR and CDP_FALLBACK_PAYAI:
                    facs.append(FACILITATOR)
            elif GO_FAC and _req_net.startswith("algorand"):
                # v44.7.0: pagamento AVM vai SÓ ao GoPlausible — regra do
                # challenge (settle fora dele não conta no leaderboard) e
                # fato técnico (PayAI/CDP não verificam ASA).
                facs = [GO_FAC]
            else:
                facs = [FACILITATOR] if FACILITATOR else []
            if not facs:
                continue
            # v44.2.3 FIX — O FALLBACK AGORA COBRE O SETLE TAMBÉM.
            # Antes: verify OK na CDP → settle CDP falhava → `continue` pulava
            # pro próximo accept sem NUNCA dar ao PayAI a chance de liquidar
            # aquele pagamento válido. E o motivo do settle falho era
            # sobrescrito pelo "network_mismatch" fantasma do accept Solana
            # (bug de leitura da rede v2, corrigido acima). Sequência real de
            # 04-06/ago: CDP verify OK → CDP settle recusou → venda morria.
            # Agora verify+settle rodam em cadeia por facilitador: se a CDP
            # verifica mas não liquida, o PayAI tenta verify+settle do MESMO
            # pagamento antes de desistir. Seguro: autorização EIP-3009 é de
            # uso único (nonce) — uma 2ª liquidação falharia on-chain.
            settled, sdata, fac = False, {}, None
            for _f in facs:
                _tag = getattr(_f, 'tag', ('CDP' if getattr(_f, 'is_cdp', False) else 'PayAI'))
                ok, reason, vdata = _f.verify(payload, req)
                if not ok:
                    # v44.2.2: motivo carimbado vai pro log E pro 402 (retorno
                    # final) — o cliente vê na hora POR QUE recusou.
                    fac_reasons[_tag] = str(reason or 'facilitator-rejected')[:140]
                    log.warning(f"⚠️ {_tag}.verify falhou p/ {endpoint}: {reason} | vdata={vdata}")
                    if _tag == 'CDP':
                        _cdp_note_failure(reason)   # v44.3.3: alimenta o disjuntor
                    continue
                # v21.2 FIX: verify() só confirma a assinatura — quem move o
                # dinheiro on-chain é settle(). bazaar blob/resource só na CDP.
                bz = _bazaar_blob(endpoint) if getattr(_f, 'is_cdp', False) else None
                _res = ({"url": f"{_public_base()}{endpoint}",
                         "description": ENDPOINT_DESC.get(endpoint, endpoint),
                         "mimeType": "application/json"}
                        if getattr(_f, 'is_cdp', False) else None)
                _ok_settle, _sdata = _f.settle(payload, req, bazaar=bz, resource=_res)
                if _ok_settle:
                    settled, sdata, fac = True, _sdata, _f
                    if _tag == 'CDP':
                        _cdp_note_success()   # v44.3.3: fecha o disjuntor na hora
                    break
                fac_reasons[_tag] = f"settle:{str(_sdata.get('error', _sdata))[:120]}"
                log.warning(f"⚠️ {_tag}.settle falhou p/ {endpoint}: {_sdata}")
                if _tag == 'CDP':
                    _cdp_note_failure(str(_sdata))   # v44.3.3: alimenta o disjuntor
            if fac_reasons:
                last_reason = "; ".join(f"{k}:{v}" for k, v in fac_reasons.items())
            if not settled or not fac:
                continue
            settle_tx = _clean_tx(sdata, tx_sig)
            # v21.9 FIX: no scheme SVM patrocinado o payload do cliente não traz
            # "payer" — o comprador real vem no SettleResponse do facilitator.
            # Sem isso, "Compradores únicos" ficava sempre 0 no dashboard.
            real_payer = (sdata.get("payer") or sdata.get("from")
                          or sdata.get("sender") or payer or "")
            if str(real_payer).startswith("0x"):
                real_payer = real_payer.lower()
            LEDGER.replay_mark(h)
            try:
                LEDGER.add_revenue(endpoint, amount, settle_tx, real_payer,
                                    source="facilitator", chain=chain)
            except Exception as _e:
                log.error(f"🚨 SETTLED-SEM-REGISTRO {endpoint} tx={settle_tx} ${amount}: {_e} — use /force-register-tx")
            _notify_telegram(f"💰 ${amount} USDC em {endpoint} ({chain}, via facilitator)\nTX: {str(settle_tx)[:32]}...")
            return True, "ok-facilitator", {"payer": real_payer, "tx": settle_tx,
                                            "settlement": sdata}
        log.warning(f"⚠️ Todos os accepts falharam no facilitator p/ {endpoint}: {last_reason}")

    if chain == "solana":
        threshold = max(0.005, amount * 0.95)
        ok, info = SOL.verify_payment(tx_sig, threshold, RECEIVE_ADDRESS)
        # v20 FIX: retry para tx-not-found (lag Helius/RPC pode demorar 3-6s)
        if not ok and isinstance(info, str) and info == "tx-not-found":
            for attempt in range(4):
                time.sleep(1.5 * (attempt + 1))  # 1.5s, 3s, 4.5s, 6s
                ok, info = SOL.verify_payment(tx_sig, threshold, RECEIVE_ADDRESS)
                if ok:
                    log.info(f"_verify_payment: recuperado após {attempt+1} retries")
                    break
                if isinstance(info, str) and info != "tx-not-found":
                    break
        if ok:
            payer_addr = info.get("payer") if isinstance(info, dict) else payer
            LEDGER.replay_mark(h)
            LEDGER.add_revenue(endpoint, amount, tx_sig, payer_addr or payer,
                                source="direct", chain="solana")
            _notify_telegram(f"💰 ${amount} USDC em {endpoint} (Solana)\nTX: {tx_sig[:32]}...")
            return True, "ok", {"payer": payer_addr or payer, "tx": tx_sig}
        return False, info if isinstance(info, str) else "verify-failed", {}
    if chain == "base":
        if not FACILITATOR and not CDP_FAC:
            return False, "base-needs-facilitator", {}
        # v44.2.2: devolve o motivo real do facilitador no 402 (truncado) —
        # o cliente vê "Payment invalid: CDP:invalid_exact_evm_..." na tela
        # em vez de um "verify-failed" genérico. Diagnóstico sem abrir log.
        _motivo = str(last_reason)[:220] if last_reason else "sem-detalhe"
        return False, f"facilitator-verify-failed: {_motivo}", {}
    return False, "unknown-chain", {}

def _notify_telegram(text: str):
    if not (TG_TOKEN and TG_CHAT): return
    try:
        requests.post(f"https://api.telegram.org/bot{TG_TOKEN}/sendMessage",
            json={"chat_id": TG_CHAT, "text": text},
            timeout=5)
    except Exception:
        pass

