# v24.4: produtos premium mostram um TEASER no preview (estrutura + resumo),
# nunca o produto inteiro — preview atrai o curioso sem canibalizar a venda.
PREMIUM_TEASER_PATHS: set = set()   # preenchido na seção 16 (Premium Suite)

def _premium_teaser(result: dict) -> dict:
    """Versão degustação de um produto premium: mantém a estrutura (chaves),
    corta a síntese e sinaliza o que a versão paga entrega."""
    try:
        teaser = {}
        for k, v in result.items():
            if isinstance(v, str) and len(v) > 220:
                teaser[k] = v[:220] + " … [full analysis in paid version]"
            elif isinstance(v, list) and len(v) > 2:
                teaser[k] = v[:2] + [f"… +{len(v)-2} more in paid version"]
            elif isinstance(v, dict):
                teaser[k] = {kk: ("…" if isinstance(vv, (dict, list)) or
                                  (isinstance(vv, str) and len(vv) > 80) else vv)
                             for kk, vv in list(v.items())[:6]}
            else:
                teaser[k] = v
        teaser["_teaser"] = True
        return teaser
    except Exception:
        return {"_teaser": True, "keys": list(result.keys())[:20]}

def _quote_ok(q) -> bool:
    """v24.10: um quote só é utilizável se tem preço real (>0) e não está
    marcado unavailable/warming/error. Usado pelos produtos premium para
    NÃO cobrar por dados vazios — a causa da rejeição no x402-list."""
    return bool(isinstance(q, dict) and q.get("price")
                and not q.get("status") and not q.get("error"))

def _premium_needs(*quotes):
    """Retorna (True, resposta_503) se faltar dado-base essencial; senão (False, None).
    503 faz o cliente NÃO ser cobrado e entender que é indisponibilidade temporária."""
    if not any(_quote_ok(q) for q in quotes):
        return True, ({"status": "unavailable",
                       "error": "Upstream market data source is temporarily unreachable. "
                                "No charge — please retry shortly.",
                       "provider": "Losbeto/Premium", "version": VERSION,
                       "ts": int(time.time())}, 503)
    return False, None

def _clean_params() -> str:
    """v29: parâmetros que a máquina enviou, sem o ruído de controle.
    É o sinal de demanda mais direto que existe: se todos pedem
    ?symbol=TSLA ou ?pair=USD/BRL, isso é o mercado falando."""
    try:
        skip = {"preview", "format", "token", "t", "_", "cb", "nocache"}
        pares = [f"{k}={v}" for k, v in request.args.items()
                 if k not in skip and v][:6]
        return "&".join(pares)[:160]
    except Exception:
        return ""

# ---------------------------------------------------------------------------
# v39 — GATE DE PRÉ-PAGAMENTO
#
# A v38 tinha _premium_needs() com o comentário "503 faz o cliente NÃO ser
# cobrado". Isso era FALSO: em paid_endpoint o _verify_payment() (que liquida
# on-chain) roda ANTES do handler. Um 503 vindo do handler chegava com o
# dinheiro já capturado. Duas correções:
#   1. gate ANTES da verificação de pagamento — se o insumo essencial está
#      fora, devolvemos 503 e o agente nunca chega a assinar nada;
#   2. estorno em crédito se a falha acontecer depois do settle (corrida).
# ---------------------------------------------------------------------------

# Endpoints em que a síntese de IA É o produto: sem LLM não sobra nada que
# justifique o preço, então não vendemos. Separados dos que DEGRADAM bem
# (/correlation-matrix devolve a matriz inteira, /sector-rotation a tabela de
# performance, /event-playbook a grade de cenários) — esses continuam à venda
# e apenas declaram ai_status="unavailable" no corpo.
