    @staticmethod
    def event_playbook():
        """Playbook de cenários para um evento macro (FOMC/NFP/CPI/ECB):
        hawkish/dovish/in-line + impacto esperado por classe de ativo."""
        event_q = request.args.get("event", "").upper()
        ts = int(time.time())
        cal = _safe_call(Brain.macro_calendar).get("events", [])
        target = None
        for e in cal:
            if event_q and event_q in e.get("event", "").upper():
                target = e
                break
        if target is None:
            highs = [e for e in cal if e.get("impact") == "high"]
            target = (highs or cal or [{"event": "FOMC", "date": "n/a"}])[0]

        gold = _safe_call(lambda: _brain_with_args(Brain.commodity_price, {"symbol": "GOLD"}))
        eur = _safe_call(lambda: _brain_with_args(Brain.forex_rate, {"pair": "EUR/USD"}))
        btc = _safe_call(Brain.pyth_price)
        spy = _safe_call(lambda: _brain_with_args(Brain.stock_quote, {"symbol": "SPY"}))
        baseline = {"gold": gold.get("price"), "eur_usd": eur.get("rate"),
                    "btc": btc.get("price"), "spy": spy.get("price")}

        scenarios = {
            "hawkish": {"usd": "stronger", "gold": "pressure", "equities": "risk-off",
                        "crypto": "downside", "probability_note": "if hotter than forecast"},
            "in_line": {"usd": "muted", "gold": "range", "equities": "relief drift",
                        "crypto": "follows equities", "probability_note": "base case"},
            "dovish": {"usd": "weaker", "gold": "bid", "equities": "risk-on",
                       "crypto": "upside beta", "probability_note": "if softer than forecast"},
        }
        narrative = _ai(
            f"You are a macro strategist. Event: {json.dumps(target, default=str)}. "
            f"Current baseline: {json.dumps(baseline, default=str)}. For each scenario "
            f"(hawkish / in-line / dovish) write 2 sentences on cross-asset positioning "
            f"(USD, gold, equities, crypto) and ONE trap to avoid. English, max 200 words.")

        return {"product": "Event Playbook", "event": target, "ts": ts,
                "baseline": baseline, "scenarios": scenarios,
                "ai_playbook": narrative or "AI narrative unavailable — scenario grid above.",
                "provider": "Losbeto/Premium", "version": VERSION,
                "disclaimer": "Research, not financial advice."}

    # ------------------------------------------------------------------ 4
    @staticmethod
    def portfolio_stress():
        """Stress test agente-para-agente: envie posições (POST JSON ou
        ?positions=[...]) e receba exposição, choques simulados e comentário AI."""
        ts = int(time.time())
        positions = None
        try:
            body = request.get_json(silent=True) or {}
            positions = body.get("positions")
        except Exception:
            pass
        if positions is None:
            try:
                positions = json.loads(request.args.get("positions", ""))
            except Exception:
                positions = None
        example_used = False
        if not isinstance(positions, list) or not positions:
            example_used = True
            positions = [{"asset": "BTC", "weight": 0.30},
                         {"asset": "NVDA", "weight": 0.25},
                         {"asset": "GOLD", "weight": 0.20},
                         {"asset": "EUR", "weight": 0.15},
                         {"asset": "USDC", "weight": 0.10}]

        CRYPTO = {"BTC", "ETH", "SOL", "BNB", "XRP", "DOGE", "ADA"}
        COMMOD = {"GOLD", "SILVER", "OIL", "OIL_WTI", "OIL_BRENT", "COPPER", "NATGAS"}
        FX = {"EUR", "GBP", "JPY", "CHF", "AUD", "CAD"}
        STABLE = {"USDC", "USDT", "USD", "DAI", "CASH"}

        def _cls(a):
            a = str(a).upper()
            if a in CRYPTO: return "crypto"
            if a in COMMOD: return "commodity"
            if a in FX: return "fx"
            if a in STABLE: return "stable"
            return "equity"

        exposure = {}
        for p in positions[:40]:
            w = float(p.get("weight", p.get("qty", 0)) or 0)
            exposure[_cls(p.get("asset", "?"))] = round(
                exposure.get(_cls(p.get("asset", "?")), 0) + w, 4)

        # sensibilidade heurística por classe (Δ% do portfólio por choque)
        SHOCKS = {
            "usd_up_2pct":   {"crypto": -3.0, "equity": -1.0, "commodity": -1.5, "fx": -2.0, "stable": 0.0},
            "oil_up_10pct":  {"crypto": -0.5, "equity": -1.5, "commodity": +4.0, "fx": 0.0, "stable": 0.0},
            "btc_down_20pct": {"crypto": -20.0, "equity": -1.0, "commodity": +0.5, "fx": 0.0, "stable": 0.0},
            "rates_up_50bp": {"crypto": -5.0, "equity": -3.0, "commodity": -1.0, "fx": -1.0, "stable": 0.0},
            "risk_off_vix_spike": {"crypto": -12.0, "equity": -6.0, "commodity": +2.0, "fx": +1.0, "stable": 0.0},
        }
        results = {}
        for name, sens in SHOCKS.items():
            pnl = sum(exposure.get(c, 0) * sens.get(c, 0) for c in exposure)
            results[name] = round(pnl, 2)
        worst = min(results, key=results.get)

        commentary = _ai(
            f"You are a risk manager. Portfolio exposure by class: {json.dumps(exposure)}. "
            f"Stress results (pct portfolio impact): {json.dumps(results)}. Worst: {worst}. "
            "Write: (1) two-sentence risk read; (2) two concrete hedging ideas; "
            "(3) the single concentration to fix first. English, max 130 words.")

        return {"product": "Portfolio Stress Test", "ts": ts,
                "positions_analyzed": len(positions), "example_portfolio": example_used,
                "exposure_by_class": exposure, "stress_scenarios_pct": results,
                "worst_scenario": worst,
                "ai_risk_commentary": commentary or "AI commentary unavailable — numbers above.",
                "methodology": "Heuristic class sensitivities; deterministic and reproducible.",
                "provider": "Losbeto/Premium", "version": VERSION,
                "disclaimer": "Research, not financial advice."}

