def _credits_purchase_handler(endpoint: str):
    def _h():
        from flask import g as _g
        plan = CREDIT_PLANS[endpoint]
        payer = getattr(_g, "losbeto_payer", "") or ""
        txinfo = getattr(_g, "losbeto_payment", {}) or {}
        tx_sig = txinfo.get("tx", "") if isinstance(txinfo, dict) else ""
        # Idempotência: retry do cliente com a MESMA tx retorna a MESMA key
        if tx_sig:
            existing = LEDGER.api_key_by_tx(tx_sig)
            if existing:
                return _credits_payload(endpoint, plan, existing["key"],
                                        existing["balance_usd"], existing["expires"],
                                        idempotent=True)
        key = "lsk_" + secrets.token_urlsafe(24)
        ttl = plan["ttl_days"] * 86400
        LEDGER.api_key_create(key, payer, plan["plan"], plan["balance_usd"], ttl, tx_sig)
        _notify_telegram(f"💳 Novo plano {plan['plan']} vendido ({plan['bonus']})\n"
                         f"Payer: {payer[:20]}...")
        return _credits_payload(endpoint, plan, key, plan["balance_usd"],
                                int(time.time()) + ttl)
    return _h

def _credits_payload(endpoint, plan, key, balance_usd, expires, idempotent=False):
    base = _public_base()
    payload = {
        "api_key": key,
        "plan": plan["plan"],
        "balance_usd": ("unlimited" if balance_usd == -1 else round(balance_usd, 6)),
        "bonus": plan["bonus"],
        "expires_ts": expires,
        "expires_iso": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(expires)),
        "idempotent_replay": idempotent,
        "how_to_use": {
            "header": f"X-API-Key: {key}",
            "example": f"curl -H 'X-API-Key: {key}' {base}/fear-greed",
            "note": ("Sem fluxo 402 por chamada — saldo debitado do ledger em ~1ms. "
                     "Confira saldo em GET /credits-status?key=..."),
        },
        "catalog": {"endpoints": len(BASE_PRICES) - len(CREDIT_PLANS),
                    "cheapest": "$0.010", "flagship": "/launch-risk",
                    "pricing": f"{base}/get-pricing"},
        "top_up": f"{base}/buy-credits",
        "provider": "Losbeto", "version": VERSION,
    }
    # v44.0.7: planos podem declarar perks extras (ex.: /founding-agent) —
    # entram no payload pago para o comprador ver o que a key dele carrega.
    if plan.get("perks"):
        payload["perks"] = plan["perks"]
        payload["badge"] = plan["plan"]
    return payload

for _ep in CREDIT_PLANS:
    app.add_url_rule(_ep, _ep.strip("/").replace("-", "_"),
                     paid_endpoint(_ep)(_credits_purchase_handler(_ep)))

@app.route("/credits-status")
def credits_status():
    """Público: saldo/validade de uma key (sem revelar payer)."""
    key = (request.args.get("key") or request.headers.get("X-API-Key") or "").strip()
    if not key:
        return jsonify({"error": "pass ?key=... ou header X-API-Key"}), 400
    row = LEDGER.api_key_get(key)
    if not row:
        return jsonify({"valid": False, "error": "key desconhecida"}), 404
    expired = bool(row["expires"] and int(time.time()) > row["expires"])
    return jsonify({
        "valid": not expired,
        "plan": row["plan"],
        "balance_usd": ("unlimited" if row["balance_usd"] == -1 else round(row["balance_usd"], 6)),
        "calls_used": row["calls_used"],
        "expires_iso": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(row["expires"])),
        "top_up": f"{_public_base()}/buy-credits",
    })


