def twitter_promo_loop():
    """v39: a v38 gerava um tweet com LLM e depois só fazia log.info dele —
    "aqui apenas logamos" está no comentário original. Ou seja: gastava cota
    de IA (o insumo escasso) para produzir texto que ninguém jamais leu.
    Agora o rascunho vai para o Telegram do operador, que decide se posta.
    Sem credenciais de Twitter configuradas o loop nem inicia."""
    if not (TWITTER_API_KEY and TWITTER_API_SECRET
            and TWITTER_ACCESS_TOKEN and TWITTER_ACCESS_TOKEN_SECRET):
        log.info("Auto-promoção no Twitter desativada (credenciais não configuradas)")
        return
    if not (TG_TOKEN and TG_CHAT):
        log.info("Auto-promoção desativada: sem Telegram para revisar o rascunho")
        return
    log.info("🐦 Rascunho de promoção diária ativo (revisão manual via Telegram)")
    while True:
        time.sleep(86400)  # 24h
        try:
            if not llm_healthy():
                continue
            fg = Market.fear_greed()
            regime = Brain.regime()
            prompt = (
                f"Write one tweet (max 260 characters) about crypto markets today "
                f"using Fear&Greed={fg.get('value')} and regime={regime.get('regime')}. "
                f"Mention that live data is available per call over x402 at "
                f"{_public_base()}. No hype, no emoji spam, no price predictions."
            )
            tweet_text = LLM.ask(prompt, max_tokens=160, temperature=0.7)
            if tweet_text:
                _notify_telegram(f"🐦 Rascunho de tweet (revise antes de postar):\n\n"
                                 f"{tweet_text[:280]}")
        except Exception as e:
            log.warning(f"twitter promo: {e}")

def autoregister_x402scan():
    time.sleep(25)
    if not PUBLIC_URL:
        log.warning("autoregister: PUBLIC_URL não definida")
        return
    try:
        r = requests.get(f"{PUBLIC_URL}/.well-known/x402.json", timeout=15)
        if not r.ok:
            log.warning(f"autoregister: manifest retornou {r.status_code}")
            return
        log.info("=" * 62)
        log.info(f"⚡ LOSBETO v{VERSION} — OPERACIONAL")
        log.info(f"   URL:         {PUBLIC_URL}")
        log.info(f"   Free tier:   {PUBLIC_URL}/sample")
        log.info(f"   Pricing:     {PUBLIC_URL}/get-pricing")
        log.info(f"   Credits:     {PUBLIC_URL}/buy-credits (1 tx → N chamadas)")
        log.info(f"   Bazaar:      {PUBLIC_URL}/bazaar.json")
        log.info(f"   x402:        {PUBLIC_URL}/.well-known/x402.json")
        log.info(f"   MCP:         {PUBLIC_URL}/.well-known/mcp.json")
        log.info(f"   llms.txt:    {PUBLIC_URL}/llms.txt")
        log.info("=" * 62)
        # ------------------------------------------------------------------
        # v39: o auto-registro da v38 fazia POST em cinco URLs que NÃO EXISTEM
        # ("https://www.x402scan.com/api/register", ".../bazaar/register" etc).
        # Os logs mostram 404 em quatro delas a cada boot — e como o gunicorn
        # recicla worker a cada ~15 min com --max-requests, isso batia em
        # endpoints inexistentes o dia inteiro. Registro em diretório agentic
        # é feito por publicação/claim, não por ping. O que sobrou aqui é o
        # que de fato serve: verificar se as NOSSAS superfícies de descoberta
        # estão de pé, e falar alto quando não estão.
        # ------------------------------------------------------------------
        surfaces = [
            ("x402 manifest",   "/.well-known/x402.json"),
            ("MCP registry",    "/server.json"),
            # v39.5: GET /mcp devolve 405 DE PROPÓSITO — a spec MCP permite
            # recusar o canal SSE server->client, e este servidor é stateless
            # sobre POST. O health check da v39.2 fazia GET e marcava ❌ a cada
            # boot. Alarme falso que eu mesmo introduzi; agora testa por POST.
            ("MCP endpoint",    "/mcp", "POST"),
            ("OpenAPI",         "/openapi.json"),
            ("llms.txt",        "/llms.txt"),
            ("llms-full.txt",   "/llms-full.txt"),
            ("agentic manifest","/.well-known/agentic.json"),
            ("free sample",     "/try"),
        ]
        quebradas = []
        for _item in surfaces:
            nome, caminho = _item[0], _item[1]
            metodo = _item[2] if len(_item) > 2 else "GET"
            try:
                if metodo == "POST":
                    rr = requests.post(f"{PUBLIC_URL}{caminho}", timeout=10,
                                       json={"jsonrpc": "2.0", "id": 1,
                                             "method": "tools/list"})
                else:
                    rr = requests.get(f"{PUBLIC_URL}{caminho}", timeout=10)
                if rr.ok:
                    log.info(f"📍 {nome:18s} ✅ {rr.status_code} "
                             f"({len(rr.content)}b)")
                else:
                    log.error(f"📍 {nome:18s} ❌ {rr.status_code} — {caminho}")
                    quebradas.append(f"{nome} ({rr.status_code})")
            except Exception as e:
                log.error(f"📍 {nome:18s} ⚠️ {str(e)[:50]} — {caminho}")
                quebradas.append(f"{nome} (erro)")
            time.sleep(0.3)

        if quebradas:
            _notify_telegram("🚨 Superfícies de descoberta com problema:\n"
                             + "\n".join(f"• {q}" for q in quebradas))

        log.info("=" * 62)
        log.info("📋 DISTRIBUIÇÃO — feita UMA VEZ, manualmente:")
        log.info("   1. MCP Registry:  mcp-publisher login github "
                 "&& mcp-publisher publish   (lê /server.json)")
        log.info("   2. x402scan:      https://www.x402scan.com/resources/register")
        log.info("   3. awesome-x402:  PR em github.com/xpaysh/awesome-x402")
        log.info("   4. AgentCash:     https://agentcash.dev — cole a URL do node")
        log.info("   5. MCPay:         https://mcpay.tech — liste o MCP")
        log.info("   6. CDP Bazaar:    1 settle em Base via POST /bootstrap-trust")
        log.info("                     (o manifesto v39 já traz Base em accepts[0])")
        log.info("=" * 62)
    except Exception as e:
        log.warning(f"autoregister erro: {e}")

# ============================================================================
# 15. AUTOPILOT v24.3 — autonomia honesta: o node se mantém sozinho.
#     (Nenhum destes loops "vende" — eles garantem que, quando um agente
#      chegar, a loja está aberta, o preview está quente e você fica sabendo.)
# ============================================================================

# Endpoints que o warmer mantém quentes (defaults dos handlers já são bons:
# forex_rate→EUR/USD, stock_quote→AAPL, commodity_price→GOLD etc.)
# ---------------------------------------------------------------------------
# v39 — WARMER DIVIDIDO EM DOIS
#
# A v38 aquecia UMA lista a cada 900s, e nela estavam /sector-rotation,
# /correlation-matrix, /launch-risk, /alpha-signal e /equity-dossier — todos
# chamam LLM. São 96 ciclos por dia × 5 endpoints ≈ 480 chamadas de LLM
# diárias para ninguém. Era exatamente isso que estourava o TPD do Groq: o
# aquecimento GRÁTIS consumia a cota inteira e, quando um agente pagante
# chegava, a cadeia de IA estava morta. Os logs mostram os 429 em rajada
# sempre imediatamente antes de "warmer: 15/15 previews atualizados".
#
# Agora: dados baratos aquecem de 15 em 15 minutos; a camada de IA aquece
# de 12 em 12 horas, que é a frequência com que uma amostra premium
# realmente precisa mudar.
# ---------------------------------------------------------------------------
AUTOPILOT_WARM = [p.strip() for p in os.environ.get(
    "AUTOPILOT_WARM_ENDPOINTS",
    "/fear-greed,/pyth-price,/trust-hash,/forex-rate,/stock-quote,"
    "/commodity-price,/macro-calendar,/regime,/dex-screen,"
    "/oracle-consensus,/sentiment-consensus,/br-macro,/br-equity"
).split(",") if p.strip()]
AUTOPILOT_WARM_SECS = int(os.environ.get("AUTOPILOT_WARM_SECS", "900"))  # 15 min

AUTOPILOT_WARM_AI = [p.strip() for p in os.environ.get(
    "AUTOPILOT_WARM_AI_ENDPOINTS",
    "/sector-rotation,/correlation-matrix,/launch-risk,/alpha-signal,"
    "/equity-dossier,/global-macro"
).split(",") if p.strip()]
AUTOPILOT_WARM_AI_SECS = int(os.environ.get("AUTOPILOT_WARM_AI_SECS", "43200"))  # 12 h
# v44.8.0: AI_WARMER=0 desliga o aquecimento de previews de IA — cada ciclo
# custa chamadas de LLM contra a cota gratuita. Em semana de cota apertada,
# o operador desliga o warmer e a cota fica 100% para quem paga.
AUTOPILOT_WARM_AI_ON = os.environ.get("AI_WARMER", "1") != "0"

def _warm_once(paths: List[str], label: str) -> int:
    ok = 0
    for path in paths:
        handler = ENDPOINT_HANDLERS.get(path)
        if not handler:
            continue
        try:
            with app.test_request_context(path):
                result = handler()
            if isinstance(result, dict) and _sample_is_good(result):
                # v28: a amostra só é renovada após envelhecer — é o
                # envelhecimento que dá valor à versão paga.
                _cur = _PREVIEW_CACHE.get(path) or _preview_db_get(path)
                _age = (time.time() - _cur["ts"]) if _cur else 1e9
                if _age >= _preview_min_age(path):
                    _PREVIEW_CACHE[path] = {"ts": time.time(), "data": result}
                    _preview_db_put(path, result)
                ok += 1
        except LLMUnavailable:
            log.debug(f"warm {path}: IA fora, amostra anterior mantida")
        except Exception as e:
            log.debug(f"warm {path}: {str(e)[:60]}")
        time.sleep(2)  # gentileza com as fontes externas
    log.info(f"🔥 warmer[{label}]: {ok}/{len(paths)} previews atualizados")
    return ok


def preview_warm_loop():
    """Aquece o cache de ?preview=1 chamando os handlers INTERNAMENTE.
    Sem isto, num node sem vendas o funil 'avalie grátis → pague' começa
    quebrado: o preview de um endpoint só existiria depois de alguém pagar."""
    time.sleep(20)  # deixa o boot terminar
    log.info(f"🔥 Autopilot warmer (dados): {len(AUTOPILOT_WARM)} endpoints "
             f"a cada {AUTOPILOT_WARM_SECS}s")
    while True:
        _warm_once(AUTOPILOT_WARM, "dados")
        time.sleep(AUTOPILOT_WARM_SECS)


def preview_warm_ai_loop():
    """Aquecimento LENTO da camada de IA. Separado de propósito: cada item
    aqui custa uma chamada de LLM, e a cota é o insumo escasso que a v38
    torrava aquecendo produtos que ninguém tinha comprado."""
    time.sleep(90)
    log.info(f"🔥 Autopilot warmer (IA): {len(AUTOPILOT_WARM_AI)} endpoints "
             f"a cada {AUTOPILOT_WARM_AI_SECS}s"
             + ("" if AUTOPILOT_WARM_AI_ON else " — DESLIGADO (AI_WARMER=0)"))
    while True:
        if not AUTOPILOT_WARM_AI_ON:
            time.sleep(AUTOPILOT_WARM_AI_SECS)
            continue
        if llm_healthy():
            _warm_once(AUTOPILOT_WARM_AI, "IA")
        else:
            log.info("🔥 warmer[IA]: pulado — nenhum provedor de LLM saudável")
        time.sleep(AUTOPILOT_WARM_AI_SECS)

def premium_brief_loop():
    """v24.4: gera o Global Morning Brief 1x/dia (autônomo, sem pagamento) e
    coloca o brief ANTERIOR como preview público — a degustação perfeita de um
    produto diário é o de ontem, completo."""
    time.sleep(45)
    while True:
        try:
            today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
            yesterday = (datetime.now(timezone.utc) - timedelta(days=1)).strftime("%Y-%m-%d")
            prev = _premium_db_get(f"brief:{yesterday}", max_age=200000)
            if not Premium._brief_is_good(prev):
                prev = None          # v25.5: nunca publicar brief ruim/antigo
            today_cached = _premium_db_get(f"brief:{today}", max_age=90000)
            fresh = None
            if not Premium._brief_is_good(today_cached):
                with app.test_request_context("/global-morning-brief"):
                    fresh = Premium._generate_brief(today)
                if Premium._brief_is_good(fresh):
                    log.info("💎 Morning Brief gerado para " + today)
                else:
                    log.warning("⚠️ Morning Brief sem dados suficientes — não publicado")
                    fresh = None
            preview_payload = prev or (_premium_teaser(fresh) if fresh else None)
            if preview_payload:
                _PREVIEW_CACHE["/global-morning-brief"] = {"ts": time.time(),
                                                           "data": preview_payload}
                _preview_db_put("/global-morning-brief", preview_payload)
        except Exception as e:
            log.warning(f"premium_brief_loop: {e}")
        time.sleep(3600)  # re-checa a cada hora (gera só na virada do dia UTC)

def _state_get(key: str, default: float = 0.0) -> float:
    """Estado pequeno que precisa sobreviver ao reciclo de worker."""
    try:
        f = HOME_DIR / f"state_{key}"
        return float(f.read_text().strip()) if f.exists() else default
    except Exception:
        return default


def _state_put(key: str, value: float) -> None:
    try:
        (HOME_DIR / f"state_{key}").write_text(str(value))
    except Exception as e:
        log.debug(f"state {key}: {e}")


def autopilot_report_loop():
    """Auto-relatório diário no Telegram.

    v39 — BUG CORRIGIDO. A v38 fazia `time.sleep(86400)` dentro do loop. Com
    `--max-requests 1000` no railway.toml, o gunicorn recicla worker a cada
    poucos minutos (os logs mostram dois restarts em 15 min), o lock de
    background migra para o worker novo e TODO loop recomeça do zero. Um sleep
    de 24h nunca chegava ao fim: este relatório jamais foi enviado, nenhuma
    vez. Agora o carimbo do último envio é persistido em disco e o loop
    acorda de hora em hora para checar se já passou um dia.
    """
    time.sleep(120)
    while True:
        try:
            last = _state_get("last_daily_report", 0.0)
            if (time.time() - last) >= 86400:
                stats = {}
                try:
                    stats = LEDGER.stats() or {}
                except Exception:
                    pass
                previews = sum(_PREVIEW_SERVED.values())
                top_prev = ", ".join(f"{k}×{v}"
                                     for k, v in _PREVIEW_SERVED.most_common(3)) or "—"
                health = llm_health_report()
                ai_line = ("IA: todos os provedores respondendo"
                           if health.get("healthy") else
                           f"🚨 IA FORA — {list(health.get('quarantined', {}))}")
                sem_venda = ""
                try:
                    ultima = float(stats.get("last_sale_ts") or 0)
                    if ultima and (time.time() - ultima) > 25 * 86400:
                        dias = int((time.time() - ultima) / 86400)
                        sem_venda = (f"\n⚠️ {dias} dias sem settle — endpoints "
                                     f"saem do Bazaar aos 30.")
                except Exception:
                    pass
                msg = (f"🤖 Relatório diário — Losbeto {VERSION}\n"
                       f"{ai_line}\n"
                       f"Previews servidos (desde o boot): {previews} ({top_prev})\n"
                       f"Ledger: {json.dumps(stats, default=str)[:380]}"
                       f"{sem_venda}")
                _notify_telegram(msg)
                _state_put("last_daily_report", time.time())
        except Exception as e:
            log.warning(f"autopilot report: {e}")
        time.sleep(3600)   # acorda de hora em hora; o carimbo decide


def llm_watchdog_loop():
    """v39 — o alerta que faltava. A cadeia de LLM caiu e ficou dias fora sem
    ninguém saber: só era possível descobrir lendo log. Aqui o operador é
    avisado na transição (fora → dentro e dentro → fora), nunca em loop."""
    time.sleep(180)
    anterior = None
    while True:
        try:
            atual = llm_healthy()
            if anterior is not None and atual != anterior:
                if atual:
                    _notify_telegram("✅ IA restabelecida — endpoints de síntese "
                                     "voltaram a ser vendidos.")
                else:
                    h = llm_health_report()
                    _notify_telegram(
                        "🚨 IA FORA em todos os provedores.\n"
                        f"Quarentena: {json.dumps(h.get('quarantined', {}))[:300]}\n"
                        "Os endpoints de síntese pararam de ser vendidos "
                        "(gate de pré-pagamento). Nenhum cliente será cobrado "
                        "por resposta vazia.")
            anterior = atual
        except Exception as e:
            log.debug(f"llm watchdog: {e}")
        time.sleep(300)




# ============================================================================
# v47.9.1-LOGINLINK — ACP SELLER OFICIAL RODANDO NO RAILWAY (via CLI oficial)
#
# Substitui o módulo SDK (modelo antigo de auth, dormente). Estratégia:
# o nó orquestra a CLI OFICIAL @virtuals-protocol/acp-cli (instalada no
# build via nixpacks.toml) em subprocessos. A sessão (token + signer P256)
# mora em /data/acp-cli — volume persistente do Railway, sobrevive a
# redeploys. Bootstrap é UMA VEZ: a thread imprime os links nos logs do
# Railway; o operador clica (login + aprovar signer) e nunca mais.
#
#   Variables: ACP_SELLER=1 · ACP_AGENT_ID=<uuid do agente 0xd459...>
# ============================================================================

_ACP_CFG_DIR = "/data/acp-cli"
_ACP_AGENT_ID_DEFAULT = "01a04598-1418-78d1-a728-98fc5118910a"  # 0xd459…f45b
_ACP_EVENTS_FILE = "/data/acp-cli/events.jsonl"
_ACP_DRAIN_S = 6
_ACP_PRICES = {"token-research": "0.2", "br-market-brief": "0.15",
               "wallet-audit": "0.15"}
_ACP_ENDPOINT = {"token-research": "/token-intel",
                 "br-market-brief": "/br-brief",
                 "wallet-audit": "/wallet-scan"}
_ACP_STATE = {"listener": None, "budget_set": set(), "submitted": set()}


def _acp_env():
    env = dict(os.environ)
    env["ACP_CONFIG_DIR"] = _ACP_CFG_DIR
    return env


def _acp_cli_ok():
    import shutil
    return shutil.which("acp") is not None


def _acp_run(args, timeout=45):
    """Roda a CLI e devolve (returncode, stdout, stderr). Nunca levanta."""
    import subprocess
    try:
        p = subprocess.run(["acp"] + args, env=_acp_env(),
                           capture_output=True, text=True, timeout=timeout)
        return p.returncode, (p.stdout or "").strip(), (p.stderr or "").strip()
    except Exception as e:
        return 99, "", str(e)[:200]


def _acp_json(out):
    try:
        s = out.find("{"); e = out.rfind("}")
        if s >= 0 and e > s:
            return json.loads(out[s:e+1])
        s = out.find("["); e = out.rfind("]")
        if s >= 0 and e > s:
            return json.loads(out[s:e+1])
    except Exception:
        pass
    return None


def _acp_ensure_auth():
    """Garante login. Imprime o link nos logs do Railway (operador clica
    uma vez). Se falhar ou expirar, gera link NOVO automaticamente."""
    import re as _re2
    while True:
        rc, out, err = _acp_run(["agent", "whoami", "--json"], timeout=30)
        if rc == 0:
            return True
        log.warning("🔗 ACP LOGIN NECESSÁRIO — iniciando fluxo (uma vez só)")
        url = rid = None
        for _tent in range(3):
            rc, out, err2 = _acp_run(["configure", "start", "--json"],
                                     timeout=45)
            j = _acp_json(out) or {}
            url, rid = j.get("url"), j.get("requestId")
            blob = (out or "") + "\n" + (err2 or "")
            if not url:
                m = _re2.search(
                    r"https://[A-Za-z0-9.-]+/acp/auth/[A-Za-z0-9/?=&_.-]+",
                    blob)
                if m:
                    url = m.group(0)
            if not rid:
                m = _re2.search(r"requestId[=:\"]+([0-9a-f]{32})", blob)
                if m:
                    rid = m.group(1)
            if url and rid:
                break
            log.error(f"acp configure start falhou rc={rc} "
                      f"tentativa={_tent+1}: out={out[:200]} "
                      f"err={err2[:300]}")
            time.sleep(15)
        if not url or not rid:
            log.error("🔗 ACP login sem URL — nova tentativa em 120s")
            time.sleep(120)
            continue
        for _ in range(60):  # até ~10 min esperando o clique
            log.warning(f"🔗🔗 CLIQUE PARA LOGAR ACP: {url}")
            rc, out, _ = _acp_run(["configure", "complete",
                                   "--request-id", rid, "--json"],
                                  timeout=30)
            j = _acp_json(out) or {}
            if j.get("status") == "authenticated":
                log.warning(f"✅ ACP autenticado: "
                            f"{j.get('walletAddress','')}")
                return True
            time.sleep(10)
        log.warning("🔗 link de login expirou sem clique — gerando NOVO")


def _acp_ensure_agent():
    agent_id = os.environ.get("ACP_AGENT_ID", _ACP_AGENT_ID_DEFAULT).strip()
    _acp_run(["agent", "use", "--agent-id", agent_id, "--json"], timeout=30)
    return agent_id


def _acp_ensure_signer(agent_id):
    rc, out, err = _acp_run(["wallet", "sign-message", "--message", "ping",
                             "--chain-id", "8453", "--json"], timeout=40)
    if rc == 0:
        return True
    if "NO_SIGNER" not in (out + err):
        log.warning(f"acp signer probe: {(err or out)[:150]}")
    log.warning("🔗 ACP SIGNER — gerando link de aprovação")
    rc, out, _ = _acp_run(["agent", "add-signer", "--agent-id", agent_id,
                           "--no-wait", "--policy", "restricted", "--json"],
                          timeout=40)
    j = _acp_json(out) or {}
    url, rid, pub = j.get("signerUrl"), j.get("requestId"), j.get("publicKey")
    if not url:
        log.error(f"add-signer falhou: {out[:150]}")
        return False
    for _ in range(30):  # link expira em 5 min
        log.warning(f"🔗🔗 APROVE O SIGNER (5 min!): {url}")
        rc, out, _ = _acp_run(["agent", "signer-status", "--agent-id", agent_id,
                               "--request-id", rid or "", "--public-key",
                               pub or "", "--json"], timeout=30)
        j = _acp_json(out) or {}
        if j.get("status") == "completed":
            log.warning("✅ ACP signer aprovado e persistido em /data")
            return True
        time.sleep(10)
    return False


def _acp_do_work(job_id, chain_id, requirement_text):
    """Executa o produto no PRÓPRIO nó e submete o deliverable."""
    req_low = (requirement_text or "").lower()
    offer = next((k for k in _ACP_ENDPOINT if k in req_low), "br-market-brief")
    ep = _ACP_ENDPOINT[offer]
    params = {}
    import re as _re
    m = _re.search(r"0x[0-9a-fA-F]{40}", requirement_text or "")
    if m and ep == "/wallet-scan":
        params["address"] = m.group(0)
    m2 = _re.search(r"\b([A-Z]{2,6})\b", requirement_text or "")
    if m2 and ep == "/token-intel":
        params["token"] = m2.group(1)
    r = requests.get(f"{_public_base()}{ep}", params=params,
                     headers={"X-Partner-Key": PARTNER_KEY}, timeout=(5, 50))
    if r.status_code != 200:
        raise RuntimeError(f"produto {ep} -> {r.status_code}")
    deliverable = json.dumps({"offer": offer, "by": _public_base() + ep,
                              "report": r.json()}, ensure_ascii=False)[:11000]
    rc, out, err = _acp_run(["provider", "submit", "--job-id", str(job_id),
                             "--deliverable", deliverable,
                             "--chain-id", str(chain_id), "--json"],
                            timeout=60)
    if rc == 0:
        log.warning(f"🏪 ACP job {job_id} ENTREGUE ({offer}, "
                    f"{len(deliverable)} chars)")
        try:
            LEDGER.log_request("/acp-seller", True, 0, "railway-acp",
                               kind="paid", ua="acp-cli/railway", params=offer)
        except Exception:
            pass
    else:
        log.error(f"🏪 submit job {job_id} falhou: {(err or out)[:150]}")
    return rc == 0
def _acp_handle_event(ev):
    jid = ev.get("jobId"); chain = ev.get("chainId", 8453)
    status = str(ev.get("status", ""))
    tools = ev.get("availableTools") or []
    roles = ev.get("roles") or []
    if "provider" not in roles:
        return
    entry = ev.get("entry") or {}
    content = entry.get("content") or ""
    if "setBudget" in tools and jid not in _ACP_STATE["budget_set"]:
        offer = next((k for k in _ACP_PRICES if k in content.lower()),
                     "br-market-brief")
        price = _ACP_PRICES[offer]
        rc, out, err = _acp_run(["provider", "set-budget", "--job-id",
                                 str(jid), "--amount", price,
                                 "--chain-id", str(chain), "--json"],
                                timeout=45)
        if rc == 0:
            _ACP_STATE["budget_set"].add(jid)
            log.warning(f"🏪 ACP job {jid}: budget ${price} ({offer})")
        else:
            log.error(f"🏪 set-budget {jid}: {(err or out)[:150]}")
    elif "submit" in tools and jid not in _ACP_STATE["submitted"]:
        if not content:  # requirement pode ter vindo em evento anterior
            rc, out, _ = _acp_run(["job", "history", "--job-id", str(jid),
                                   "--chain-id", str(chain), "--json"],
                                  timeout=30)
            hist = _acp_json(out) or {}
            msgs = hist.get("messages") or []
            content = next((m.get("content", "") for m in msgs
                            if m.get("contentType") == "requirement"), "")
        if _acp_do_work(jid, chain, content):
            _ACP_STATE["submitted"].add(jid)


def _acp_start_listener():
    """Um listener por arquivo (regra da CLI). Reinicia se morrer."""
    import subprocess
    lp = _ACP_STATE.get("listener")
    if lp and lp.poll() is None:
        return
    try:
        os.makedirs(_ACP_CFG_DIR, exist_ok=True)
        _ACP_STATE["listener"] = subprocess.Popen(
            ["acp", "events", "listen", "--output", _ACP_EVENTS_FILE,
             "--json"], env=_acp_env(),
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        log.warning("🏪 ACP listener de eventos ativo (Railway)")
    except Exception as e:
        log.error(f"🏪 listener ACP falhou: {str(e)[:120]}")


def acp_railway_seller_loop():
    if os.environ.get("ACP_SELLER", "") != "1":
        return
    if not _acp_cli_ok():
        log.warning("🏪 ACP_SELLER=1 mas a CLI 'acp' não está no PATH — "
                    "confira se o nixpacks.toml está no repositório")
        return
    time.sleep(20)  # deixa o gunicorn subir primeiro
    try:
        _acp_ensure_auth()  # loop até logar
        agent_id = _acp_ensure_agent()
        while not _acp_ensure_signer(agent_id):
            log.warning("🔗 signer expirou/falhou — link NOVO em 60s")
            time.sleep(60)
        log.warning("🏪🏪 VENDEDOR ACP NO RAILWAY — ONLINE E ARMADO")
    except Exception as e:
        log.error(f"🏪 bootstrap ACP: {str(e)[:150]}")
        return
    while True:
        try:
            _acp_start_listener()
            rc, out, _ = _acp_run(["events", "drain", "--file",
                                   _ACP_EVENTS_FILE, "--limit", "10",
                                   "--json"], timeout=30)
            j = _acp_json(out) or {}
            for ev in (j.get("events") or []):
                try:
                    _acp_handle_event(ev)
                except Exception as e:
                    log.error(f"🏪 evento ACP: {str(e)[:120]}")
        except Exception as e:
            log.error(f"🏪 drain ACP: {str(e)[:120]}")
        time.sleep(_ACP_DRAIN_S)


_BG_STARTED = False
def _start_background_once():
    """Inicia TODOS os loops de background exatamente uma vez por container.

    BUG CORRIGIDO (v24.3): o railway.toml sobe o app com
    `gunicorn ... nexus_omega:app` — isso IMPORTA o módulo mas nunca chama
    run_server(). Resultado em produção: sweeper, telegram, signal generator,
    autoregister e afins NUNCA rodaram no Railway. Agora o boot acontece no
    import, com file-lock para que só UM worker rode os loops (evita
    duplicar notificações/registros com 2 workers)."""
    global _BG_STARTED
    if _BG_STARTED:
        return
    _BG_STARTED = True
    try:
        import fcntl
        _lock_f = open(HOME_DIR / "bg_loops.lock", "w")
        try:
            fcntl.flock(_lock_f, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            log.info("⏭ loops de background já ativos em outro worker")
            return
        globals()["_BG_LOCK_FILE"] = _lock_f  # mantém o lock vivo
    except Exception as e:
        log.warning(f"bg lock indisponível ({e}) — seguindo sem lock")
    threading.Thread(target=signal_validator_loop, daemon=True).start()
    threading.Thread(target=signal_generator_loop, daemon=True).start()
    threading.Thread(target=rag_ingest_loop, daemon=True).start()
    threading.Thread(target=sweeper_loop, daemon=True).start()
    if TG_BOT:
        threading.Thread(target=telegram_loop, daemon=True).start()
    threading.Thread(target=twitter_promo_loop, daemon=True).start()
    threading.Thread(target=autoregister_x402scan, daemon=True).start()
    threading.Thread(target=preview_warm_loop, daemon=True).start()
    threading.Thread(target=preview_warm_ai_loop, daemon=True).start()
    threading.Thread(target=premium_brief_loop, daemon=True).start()
    threading.Thread(target=archive_loop, daemon=True).start()
    threading.Thread(target=demand_watch_loop, daemon=True).start()
    threading.Thread(target=autopilot_report_loop, daemon=True).start()
    threading.Thread(target=llm_watchdog_loop, daemon=True).start()
    threading.Thread(target=acp_railway_seller_loop, daemon=True).start()
    log.info("✅ Autopilot: loops de background ativos neste worker")

def run_server():
    _start_background_once()

    log.info("=" * 72)
    log.info(f"⚡ LOSBETO v{VERSION} — ATIVO (REVOLUTIONARY)")
    log.info(f"   Node ID:    {WALLET.node_id}")
    log.info(f"   RECEIVE:    {RECEIVE_ADDRESS}")
    log.info(f"   SIGNER:     {WALLET.solana_address}")
    if TON_WALLET:
        log.info(f"   TON:        {TON_WALLET.address}")
    if ENABLE_BASE:
        log.info(f"   Base EVM:   {BASE_PAYTO_EVM}")
    if BINANCE_ADDRESS:
        log.info(f"   Sweep →     {BINANCE_ADDRESS}")
    log.info(f"   URL:        {_public_base()}")
    log.info(f"   Dashboard:  {_public_base()}/dash?token={DASH_TOKEN}")
    log.info(f"   Telegram:   {'ATIVO' if TG_BOT else 'off'}")
    log.info(f"   Facilitator:{'ATIVO ' + FACILITATOR_URL if FACILITATOR else 'off'}")
    log.info(f"   Dynamic:    {'ATIVO' if DYNAMIC_PRICING else 'off'}")
    log.info(f"   GeoIP:      {'ATIVO' if GEOIP_ENABLED else 'off'}")
    log.info(f"   Endpoints:  {len(BASE_PRICES)}")
    log.info(f"   Referral:   ATIVO (/referral)")
    log.info(f"   Stake:      ATIVO (/stake)")
    log.info("=" * 72)

    try:
        from gunicorn.app.base import BaseApplication
        class _G(BaseApplication):
            def __init__(self, app, opts): self.app_app = app; self.opts = opts; super().__init__()
            def load_config(self):
                for k, v in self.opts.items(): self.cfg.set(k, v)
            def load(self): return self.app_app
        opts = {
            "bind":     f"0.0.0.0:{X402_PORT}",
            "workers":  int(os.environ.get("GUNICORN_WORKERS", "2")),
            "threads":  int(os.environ.get("GUNICORN_THREADS", "8")),
            "timeout":  60,
            "accesslog": "-",
            "errorlog":  "-",
            "loglevel":  "info",
        }
        _G(app, opts).run()
    except ImportError:
        app.run(host="0.0.0.0", port=X402_PORT, threaded=True, use_reloader=False)


